INSERT INTO public.autor VALUES (1232, 'John Ronald Reuel Tolkien (1892-1973) was a major scholar of the English language, specialising in Old and Middle English. Twice Professor of Anglo-Saxon (Old English) at the University of Oxford, he also wrote a number of stories, including most famously The Hobbit (1937) and The Lord of the Rings (1954-1955), which are set in a pre-historic era in an invented version of the world which he called by the Middle English name of Middle-earth. This was peopled by Men (and women), Elves, Dwarves, Trolls, Orcs (or Goblins) and of course Hobbits. He has regularly been condemned by the Eng. Lit. establishment, with honourable exceptions, but loved by literally millions of readers worldwide.INSERT INTO public.autor VALUES (1233, 'Gabriel García Márquez is a Colombian novelist, short-story writer, screenwriter and journalist. García Márquez, affectionately known as "Gabo" throughout Latin America, is considered one of the most significant authors of the 20th century. In 1982, he was awarded the Nobel Prize in Literature. He pursued a self-directed education that resulted in his leaving law school for a career in journalism. From early on, he showed no inhibitions in his criticism of Colombian and foreign politics. In 1958, he married Mercedes Barcha; they have two sons, Rodrigo and Gonzalo.INSERT INTO public.autor VALUES (1234, 'George Orwell, originally born as Eric Arthur Blair, was an English novelist and journalist. His work is marked by keen intelligence and wit, a profound awareness of social injustice, an intense, revolutionary opposition to totalitarianism, a passion for clarity in language and a belief in democratic socialism. ([Source][1].)INSERT INTO public.autor VALUES (1235, 'Antoine de Saint-Exupéry (29 June 1900—31 July 1944) was a French writer and aviator. He is best remembered for his novella *The Little Prince (Le Petit Prince)*, and for his books about aviation adventures, including Night Flight and Wind, Sand and Stars.INSERT INTO public.autor VALUES (1236, 'George Raymond Richard Martin (born September 20, 1948), sometimes referred to as GRRM, is an American author and screenwriter of fantasy, horror, and science fiction. He is best known for his ongoing *A Song of Ice and Fire* series of epic fantasy novels.INSERT INTO public.autor VALUES (1237, 'American author of young adult literature, whose works include *The Hunger Games* trilogy and *The Underland Chronicles* series. The daughter of an Air Force officer, she lives in her native home of Connecticut.', 'https://covers.openlibrary.org/a/olid/OL1394359A-M.jpg', NULL, 'Suzanne Collins', 0);
INSERT INTO public.autor VALUES (1238, 'Veronica grew up outside of Chicago and graduated from Northwestern University. She now lives in Chicago proper with her husband and dog and writes full-time.  She is the #1 New York Times bestselling author of Carve the Mark and the Divergent Series (Divergent, Insurgent, Allegiant, and Four: A Divergent Collection). The Divergent Series was developed into three major motion pictures.', 'https://covers.openlibrary.org/a/olid/OL6895646A-M.jpg', NULL, 'Veronica Roth', 0);
INSERT INTO public.autor VALUES (1239, 'American writer of children’s fantasy novels', 'https://covers.openlibrary.org/a/olid/OL30765A-M.jpg', NULL, 'Rick Riordan', 0);
INSERT INTO public.autor VALUES (1308, 'Walter Isaacson, the CEO of the Aspen Institute, has been chairman of CNN and the managing editor of Time magazine. He is the author of Steve Jobs; Einstein: His Life and Universe; Benjamin Franklin: An American Life; and Kissinger: A Biography, and the coauthor of The Wise Men: Six Friends and the World They Made. He lives in Washington, DC.INSERT INTO public.autor VALUES (1317, NULL, 'https://covers.openlibrary.org/a/olid/OL528741A-M.jpg', NULL, 'Maida Silverman', 0);
INSERT INTO public.autor VALUES (1318, NULL, 'https://covers.openlibrary.org/a/olid/OL7730463A-M.jpg', NULL, 'Desconocido', 0);
INSERT INTO public.autor VALUES (1320, NULL, 'https://covers.openlibrary.org/a/olid/OL6003607A-M.jpg', NULL, 'Henry Chandler Cowles', 0);
INSERT INTO public.autor VALUES (1321, NULL, 'https://covers.openlibrary.org/a/olid/OL7622198A-M.jpg', NULL, 'Jennifer Simkins', 0);
INSERT INTO public.autor VALUES (1322, NULL, 'https://covers.openlibrary.org/a/olid/OL3556566A-M.jpg', NULL, 'Perfection Learning Corporation', 0);
INSERT INTO public.autor VALUES (1323, NULL, 'https://covers.openlibrary.org/a/olid/OL7899986A-M.jpg', NULL, 'Kieran Tranter', 0);
INSERT INTO public.autor VALUES (1324, NULL, 'https://covers.openlibrary.org/a/olid/OL7484749A-M.jpg', NULL, 'Donald E. Palumbo', 0);
INSERT INTO public.autor VALUES (1337, NULL, 'https://covers.openlibrary.org/a/olid/OL130252A-M.jpg', NULL, 'Bernardino de Pantorba', 0);
INSERT INTO public.autor VALUES (1338, NULL, 'https://covers.openlibrary.org/a/olid/OL682088A-M.jpg', NULL, 'José Manuel Groot', 0);
INSERT INTO public.autor VALUES (1240, 'an American novelist and film producer. She is best known for writing the vampire romance series Twilight.INSERT INTO public.autor VALUES (1241, NULL, 'https://covers.openlibrary.org/a/olid/OL1514025A-M.jpg', NULL, 'James Dashner', 0);
INSERT INTO public.autor VALUES (1242, NULL, 'https://covers.openlibrary.org/a/olid/OL23335A-M.jpg', NULL, 'Josh McDowell', 0);
INSERT INTO public.autor VALUES (1243, 'Carlos Ruiz Zafón (Barcelona, 25 de septiembre de 1964-Los Ángeles, 19 de junio de 2020) fue un novelista español. Su obra más famosa es *La sombra del viento,* ganadora de numerosos galardones, y que fue seleccionada en la lista confeccionada en 2007 por 81 escritores y críticos latinoamericanos y españoles entre los cien mejores libros en lengua española de los últimos 25 años.INSERT INTO public.autor VALUES (1244, NULL, 'https://covers.openlibrary.org/a/olid/OL10435051A-M.jpg', NULL, 'Paula Hawkins', 0);
INSERT INTO public.autor VALUES (1245, 'Stephen Edwin King (born September 21, 1947) is an American author of horror, supernatural fiction, suspense, crime, science-fiction, and fantasy novels. His books have sold more than 350 million copies, and many have been adapted into films, television series, miniseries, and comic books. King has published 63 novels, including seven under the pen name Richard Bachman, and five non-fiction books. He has also written approximately 200 short stories, most of which have been published in book collections.INSERT INTO public.autor VALUES (1246, NULL, 'https://covers.openlibrary.org/a/olid/OL11566614A-M.jpg', NULL, 'Javier H. Murillo', 0);
INSERT INTO public.autor VALUES (1247, NULL, 'https://covers.openlibrary.org/a/olid/OL31727A-M.jpg', NULL, 'Bram Stoker', 0);
INSERT INTO public.autor VALUES (1248, 'Jane Austen was an English writer. Although Austen was widely read in her lifetime, she published her works anonymously. The most urgent preoccupations of her bright, young heroines are courtship and marriage. Austen herself never married. Her best-known books include *Pride and Prejudice* (1813) and *Emma* (1816). Virginia Woolf called Austen "the most perfect artist among women.', 'https://covers.openlibrary.org/a/olid/OL21594A-M.jpg', NULL, 'Jane Austen', 0);
INSERT INTO public.autor VALUES (1249, 'Emily Jane Brontë was an English novelist and poet, now best remembered for her novel [Wuthering Heights][1], a classic of English literature. Emily was the second eldest of the three surviving Brontë sisters, between Charlotte and Anne. She published under the androgynous pen name Ellis Bell. ([Source][2].)INSERT INTO public.autor VALUES (1250, NULL, 'https://covers.openlibrary.org/a/olid/OL3778242A-M.jpg', NULL, 'Yuval Noah Harari', 0);
INSERT INTO public.autor VALUES (1251, NULL, 'https://covers.openlibrary.org/a/olid/OL7422948A-M.jpg', NULL, 'James Clear', 0);
INSERT INTO public.autor VALUES (1252, NULL, 'https://covers.openlibrary.org/a/olid/OL11089188A-M.jpg', NULL, 'Libros Maestros', 0);
INSERT INTO public.autor VALUES (1253, 'Paulo Coelho Netto, born in Campinas, Brasil, was a Brazilian writer. He was the son of the writer Henrique Maximiano Coelho Netto (1864-1934). He published some works about his father, including his biography (1956). He wrote the book *História do Fluminense*, released in 1952, and a second volume in 1968. Among others, he also wrote books about flying saucers in the 1960s and 70s.INSERT INTO public.autor VALUES (1309, NULL, 'https://covers.openlibrary.org/a/olid/OL1194290A-M.jpg', NULL, 'Brian Herbert', 0);
INSERT INTO public.autor VALUES (1310, 'Ed Naha is an American science fiction and mystery writer and producer. He was born June 10, 1950 in the town of Linden, New Jersey. His first known publication was artwork that appeared in the first issue of Modern Monsters magazine, dated June 1966. His early career was as a journalist, writing pieces about film and rock music for American magazines. He worked as publicist for music records producers and also produced records on his own.INSERT INTO public.autor VALUES (1311, NULL, 'https://covers.openlibrary.org/a/olid/OL2393191A-M.jpg', NULL, 'Earl Howell Reed', 0);
INSERT INTO public.autor VALUES (1312, NULL, NULL, NULL, 'Mark E. Leadon', 0);
INSERT INTO public.autor VALUES (1254, 'Patrick Rothfuss (born June 6, 1973) is an American author, best known for his epic fantasy series *The Kingkiller Chronicle*. Born in Madison, Wisconsin, he matriculated at the University of Wisconsin-Stevens Point, initially studying chemical engineering before switching to English.INSERT INTO public.autor VALUES (1255, NULL, 'https://covers.openlibrary.org/a/olid/OL1758387A-M.jpg', NULL, 'Frank Herbert', 0);
INSERT INTO public.autor VALUES (1256, 'Asimov was born sometime between October 4, 1919 and January 2, 1920 in Petrovichi in Smolensk Oblast, RSFSR (now Russia), the son of a Jewish family of millers.  Although his exact date of birth is uncertain, Asimov himself celebrated it on January 2.  His family emigrated to Brooklyn, New York and opened a candy store when he was three years old.  He taught himself to read at the age of five. He began reading the science fiction pulp magazines that his family''s store carried. Around the age of eleven, he began to write his own stories, and by age nineteen, he was selling them to the science fiction magazines. He graduated from Columbia University in 1939. He married Gertrude Blugerman in 1942.  During World War II he worked as a civilian at the Philadelphia Navy Yard''s Naval Air Experimental Station.  After the war, he returned to Columbia University and earned a Ph.D. in biochemistry in 1948.  He then joined the faculty of the Boston University School of Medicine until 1958, when he became a full-time writer. His first novel, [Pebble in the Sky](https://openlibrary.org/works/OL46402W), was published in 1950. He and his wife divorced in 1973, and he married Janet O. Jeppson the same year. He was a highly prolific writer, having written or edited more than 500 books and an estimated 9,000 letters and postcards.', 'https://covers.openlibrary.org/a/olid/OL34221A-M.jpg', NULL, 'Isaac Asimov', 0);
INSERT INTO public.autor VALUES (1257, 'Ray Bradbury is one of those rare individuals whose writing has changed the way people think. His more than five hundred published works -- short stories, novels, plays, screenplays, television scripts, and verse -- exemplify the American imagination at its most creative. INSERT INTO public.autor VALUES (1258, 'Russian novelist Fyodor Mikhailovitch Dostoyevsky was a journalist and short-story writer, whose psychological penetration into the human soul profoundly influenced the 20th century novel. Dostoevsky''s novels have much autobiographical elements, but ultimately they deal with moral and philosophical questions. He presented interacting characters with contrasting views or ideas about freedom of choice, Socialism, atheisms, good and evil, happiness and so forth. Dostoevsky''s central obsession was God, whom his characters constantly search through painful errors and humiliations. ([Source](http://www.kirjasto.sci.fi/fdosto.htm))INSERT INTO public.autor VALUES (1259, 'Francis Scott Key Fitzgerald was an American author of novels and short stories, whose works are evocative of the Jazz Age, a term he coined himself. He is widely regarded as one of the twentieth century''s greatest writers. Fitzgerald is considered a member of the "Lost Generation" of the Twenties. He finished four novels, *This Side of Paradise*, *The Beautiful and Damned*, *Tender Is the Night* and his most famous, the celebrated classic, *The Great Gatsby*. A fifth, unfinished novel, *The Love of the Last Tycoon* was published posthumously. Fitzgerald also wrote many short stories that treat themes of youth and promise along with despair and age. ([Wikipedia][1])INSERT INTO public.autor VALUES (1260, 'Nelle Harper Lee was an American novelist. She wrote the 1960 novel *To Kill a Mockingbird* that won the 1961 Pulitzer Prize and became a classic of modern American literature. Lee received numerous accolades and honorary degrees, including the Presidential Medal of Freedom in 2007 which was awarded for her contribution to literature. She assisted her close friend Truman Capote in his research for the book *In Cold Blood* (1966). Capote was the basis for the character Dill Harris in *To Kill a Mockingbird.*', 'https://covers.openlibrary.org/a/olid/OL498120A-M.jpg', NULL, 'Harper Lee', 0);
INSERT INTO public.autor VALUES (1261, 'Aldous Leonard Huxley (26 July 1894 – 22 November 1963) was an English writer and philosopher. He wrote nearly 50 books, both novels and non-fiction works, as well as wide-ranging essays, narratives, and poems.', 'https://covers.openlibrary.org/a/olid/OL19767A-M.jpg', NULL, 'ALDOUX HUXLEY', 0);
INSERT INTO public.autor VALUES (1262, NULL, 'https://covers.openlibrary.org/a/olid/OL11987407A-M.jpg', NULL, 'Vincent Guillaume', 0);
INSERT INTO public.autor VALUES (1263, NULL, NULL, NULL, 'Gabri Garcia Marquez', 0);
INSERT INTO public.autor VALUES (1294, 'Born in Providence, Rhode Island, Lovecraft spent most of his life in New England. INSERT INTO public.autor VALUES (1295, 'Neil Richard MacKinnon Gaiman born Neil Richard Gaiman, 10 November 1960) is an English author of short fiction, novels, comic books, graphic novels, audio theatre, and films. His notable works include the comic book series The Sandman and novels Stardust, American Gods, Coraline, and The Graveyard Book. He has won numerous awards, including the Hugo, Nebula, and Bram Stoker awards, as well as the Newbery and Carnegie medals. He is the first author to win both the Newbery and the Carnegie medals for the same work, The Graveyard Book (2008). In 2013, The Ocean at the End of the Lane was voted Book of the Year in the British National Book Awards.', 'https://covers.openlibrary.org/a/olid/OL53305A-M.jpg', NULL, 'Neil Gaiman', 0);
INSERT INTO public.autor VALUES (1264, 'Isabel Angélica Allende Llona (Lima, Perú; 2 de agosto de 1942)​ es una escritora chilena con nacionalidad estadounidense, de ascendencia hispano-portuguesa y nacida en Perú. Desde 2004 es miembro de la Academia Estadounidense de las Artes y las Letras. Obtuvo el Premio Nacional de Literatura de su país en 2010. La venta total de sus libros alcanza 73 millones de ejemplares y sus obras han sido traducidas a 42 idiomas. Es considerada como la escritora viva más leída del mundo de la lengua española.INSERT INTO public.autor VALUES (1265, NULL, 'https://covers.openlibrary.org/a/olid/OL85306A-M.jpg', NULL, 'Laura Esquivel', 0);
INSERT INTO public.autor VALUES (1266, 'Julio Florencio Cortázar (Ixelles, 26 de agosto de 1914-París, 12 de febrero de 1984) fue un escritor, poeta y profesor argentino. También trabajó como traductor, oficio que desempeñó para la Unesco y varias editoriales. En 1981, sin renunciar a su nacionalidad argentina, optó por la francesa en protesta contra la dictadura militar en su país, que prohibió sus libros y que él denunció a la prensa internacional desde su residencia en París. Se lo considera uno de los autores más innovadores y originales de su tiempo, maestro del relato corto, la prosa poética y la narración breve en general, y creador de importantes novelas, en la cual destaca *Rayuela,* que inauguraron una nueva forma de hacer literatura en el mundo hispano. Junto a Gabriel García Márquez, Mario Vargas Llosa y Carlos Fuentes, fue uno de los exponentes centrales del *boom* latinoamericano.INSERT INTO public.autor VALUES (1267, 'Juan Nepomuceno Carlos Pérez Rulfo Vizcaíno ​(Apulco, Jalisco, 16 de mayo de 1917 - Ciudad de México, 7 de enero de 1986) fue un escritor, guionista y fotógrafo mexicano, perteneciente a la Generación del 52. Es considerado uno de los escritores latinoamericanos más importantes del siglo XX. Su reputación se asienta en dos de sus tres obras narrativas: el libro de cuentos *El llano en llamas,* publicado en 1953, y la novela *Pedro Páramo,* publicada en 1955.INSERT INTO public.autor VALUES (1268, 'Ernesto Sabato (Rojas, Buenos Aires, 24 de junio de 1911-Santos Lugares, Buenos Aires, 30 de abril de 2011) fue un escritor, pintor y físico argentino. Su obra narrativa consiste en tres novelas: *El túnel, Sobre héroes y tumbas* y *Abaddón el exterminador.* También se destacó como ensayista en libros como *Uno y el Universo, Hombres y engranajes, El escritor y sus fantasmas* y *Apologías y rechazos,* en los que reflexiona sobre la condición humana, la vocación de la escritura o los problemas culturales del siglo XX. Fue el segundo argentino galardonado con el Premio Miguel de Cervantes (1984), después de Jorge Luis Borges (1979). INSERT INTO public.autor VALUES (1269, 'Noah Gordon (born November 11, 1926) is an American novelist. He was born in Worcester, Massachusetts. INSERT INTO public.autor VALUES (1270, 'Umberto Eco (5 January 1932 – 19 February 2016) was an Italian novelist, literary critic, philosopher, semiotician, and university professor. He is widely known for his 1980 novel Il nome della rosa (The Name of the Rose), a historical mystery combining semiotics in fiction with biblical analysis, medieval studies, and literary theory. He later wrote other novels, including Il pendolo di Foucault (Foucault''s Pendulum) and L''isola del giorno prima (The Island of the Day Before). His novel Il cimitero di Praga (The Prague Cemetery), released in 2010, topped the bestseller charts in Italy.INSERT INTO public.autor VALUES (1271, 'Patrick Süskind is a German writer and screenwriter, best known for his internationally acclaimed novel Perfume: The Story of a Murderer, first published in 1985.INSERT INTO public.autor VALUES (1272, NULL, 'https://covers.openlibrary.org/a/olid/OL4271523A-M.jpg', NULL, 'John Green', 0);
INSERT INTO public.autor VALUES (1296, NULL, NULL, NULL, 'Charlotte Naylor-Davis', 0);
INSERT INTO public.autor VALUES (1319, NULL, 'https://covers.openlibrary.org/a/olid/OL2503509A-M.jpg', NULL, 'John Robertson Dunlap', 0);
INSERT INTO public.autor VALUES (1273, 'Pauline Sara Jo Moyes was born on 4 August 1969 and in Maidstone, Kent, England, UK, but  grew up in London. She was the only child of Elizabeth J. McKee and James C. Moyes. She studied at Royal Holloway, University of London and Bedford New College, London University. She lives on a farmhouse in Great Sampford, Essex with her husband, journalist Charles Arthur, and their three children.INSERT INTO public.autor VALUES (1274, NULL, 'https://covers.openlibrary.org/a/olid/OL11387150A-M.jpg', NULL, 'Alton Fry Jr.', 0);
INSERT INTO public.autor VALUES (1275, 'Photo: © Philippa Gedge', 'https://covers.openlibrary.org/a/olid/OL7414871A-M.jpg', NULL, 'Gail Honeyman', 0);
INSERT INTO public.autor VALUES (1276, NULL, 'https://covers.openlibrary.org/a/olid/OL7166036A-M.jpg', NULL, 'Fredrik Backman', 0);
INSERT INTO public.autor VALUES (1277, 'Photo source: https://www.simonandschuster.com/authors/Stephen-Chbosky/1843916', 'https://covers.openlibrary.org/a/olid/OL76675A-M.jpg', NULL, 'Stephen Chbosky', 0);
INSERT INTO public.autor VALUES (1278, 'ERNEST CLINE is an internationally best-selling novelist, screenwriter, father, and full-time geek. He is the author of the novels Ready Player One and Armada and co-screenwriter of the film adaptation of Ready Player One, directed by Steven Spielberg. His books have been published in over fifty countries and have spent more than 100 weeks on The New York Times Best Sellers list. He lives in Austin, Texas, with his family, a time-traveling DeLorean, and a large collection of classic video games.', 'https://covers.openlibrary.org/a/olid/OL6941868A-M.jpg', NULL, 'Ernest Cline', 0);
INSERT INTO public.autor VALUES (1279, 'Andy Weir built a career as a software engineer until the success of his first published novel, THE MARTIAN, allowed him to live out his dream of writing fulltime. He is a lifelong space nerd and a devoted hobbyist of subjects such as relativistic physics, orbital mechanics, and the history of manned spaceflight. He also mixes a mean cocktail. He lives in California.', 'https://covers.openlibrary.org/a/olid/OL7234434A-M.jpg', NULL, 'Andy Weir', 0);
INSERT INTO public.autor VALUES (1280, 'Cassandra Clare was born overseas and spent her early years traveling around the world with her family and several trunks of fantasy books. Cassandra worked for several years as an entertainment journalist for the Hollywood Reporter before turning her attention to fiction. She is the author of City of Bones, the first book in the Mortal Instruments trilogy and a New York Times bestseller. Cassandra lives with her fiance and their two cats in Massachusetts.', 'https://covers.openlibrary.org/a/olid/OL2821271A-M.jpg', NULL, 'Cassandra Clare', 0);
INSERT INTO public.autor VALUES (1281, 'Sarah J. Maas is the #1 New York Times and internationally bestselling author of the Crescent City, A Court of Thorns and Roses, and the Throne of Glass series. Her books have sold more than twelve million copies and are published in thirty-seven languages. A New York native, Sarah lives in Philadelphia with her husband, son, and dog. To find out more, visit sarahjmaas.com or follow @therealsjmaas on Instagram.', 'https://covers.openlibrary.org/a/olid/OL7115219A-M.jpg', NULL, 'Sarah J. Maas', 0);
INSERT INTO public.autor VALUES (1282, 'American writer of young-adult speculative fiction', 'https://covers.openlibrary.org/a/olid/OL6788551A-M.jpg', NULL, 'Kiera Cass', 0);
INSERT INTO public.autor VALUES (1283, 'Laura Gallego García (born in Quart de Poblet, Valencia (Spain) on 11 October 1977) is a Spanish author of young adult literature.', 'https://covers.openlibrary.org/a/olid/OL554423A-M.jpg', NULL, 'Laura Gallego', 0);
INSERT INTO public.autor VALUES (1284, NULL, 'https://covers.openlibrary.org/a/olid/OL286087A-M.jpg', NULL, 'Ildefonso Falcones', 0);
INSERT INTO public.autor VALUES (1285, 'Fernando Aramburu es autor de los libros de cuentos ***Los peces de la amargura*** (2006, XI Premio Mario Vargas Llosa NH, IV Premio Dulce Chacón y Premio Real Academia Española 2008), ***El vigilante del fiordo*** (2011) y ***Hombre caído*** (2025), de las obras de no ficción ***Autorretrato sin mí*** (2018), ***Vetas profundas*** (2019) y ***Utilidad de las desgracias*** (2020), así como de las novelas ***Fuegos con limón*** (1996), ***Los ojos vacíos*** (2000, Premio Euskadi), ***El trompetista del Utopía*** (2003), ***Bami sin sombra*** (2005), ***Viaje con Clara por Alemania*** (2010), ***Años lentos*** (2012, VII Premio Tusquets Editores de Novela y Premio de los Libreros de Madrid), ***La gran Marivián*** (2013), ***Ávidas pretensiones*** (Premio Biblioteca Breve 2014) y ***Patria*** (2016, Premio Nacional de Narrativa, Premio de la Crítica, Premio Euskadi, Premio Francisco Umbral, Premio Dulce Chacón, Premio Arcebispo Juan de San Clemente, Premio Strega Europeo, Premio Lampedusa, Premio Atenas, entre otros), el último gran fenómeno literario español, traducida a 35 lenguas y convertida en prestigiosa serie. ***Los vencejos*** (2021), ácida y enternecedora, ***Hijos de la fábula*** (2023) y ***El niño*** (2024) lo han confirmado como uno de los mejores escritores europeos. Ha recogido su poesía completa en ***Sinfonía corporal*** (2023).INSERT INTO public.autor VALUES (1297, 'Orson Scott Card is an American novelist, critic, public speaker, essayist and columnist. He writes in several genres but is known best for science fiction. His novel Ender''s Game (1985) and its sequel Speaker for the Dead (1986) both won Hugo and Nebula Awards, making Card the only author to win both science fiction''s top U.S. prizes in consecutive years.', 'https://covers.openlibrary.org/a/olid/OL25161A-M.jpg', NULL, 'Orson Scott Card', 0);
INSERT INTO public.autor VALUES (1298, 'American playwright and novelist, who won the Tony Award for Best Play for The Miracle Worker in 1959, which he later adapted for the film version in 1962.', 'https://covers.openlibrary.org/a/olid/OL967888A-M.jpg', NULL, 'William Gibson', 0);
INSERT INTO public.autor VALUES (1299, NULL, 'https://covers.openlibrary.org/a/olid/OL2892848A-M.jpg', NULL, 'Juan A. Peña', 0);
INSERT INTO public.autor VALUES (1300, 'Stanisław Herman Lem (ur. 12 lub 13 września 1921 we Lwowie, zm. 27 marca 2006 w Krakowie) – polski pisarz gatunku hard science fiction, filozof, futurolog oraz krytyk literacki. Jest najczęściej tłumaczonym polskim pisarzem. Został odznaczony wieloma wysokimi odznaczeniami państwowymi i kulturalnymi, między innymi Orderem Orła Białego i medalem „Gloria Artis”.INSERT INTO public.autor VALUES (1301, NULL, 'https://covers.openlibrary.org/a/olid/OL16029277A-M.jpg', NULL, 'Cixin Liu', 0);
INSERT INTO public.autor VALUES (1302, NULL, 'https://covers.openlibrary.org/a/olid/OL242220A-M.jpg', NULL, 'Robert T. Kiyosaki', 0);
INSERT INTO public.autor VALUES (1313, 'William Allen White (February 10, 1868 – January 29, 1944) was an American newspaper editor, politician, author, and leader of the Progressive movement. Between 1896 and his death, White became a spokesman for middle America. -WikipediaINSERT INTO public.autor VALUES (1314, NULL, 'https://covers.openlibrary.org/a/olid/OL2396911A-M.jpg', NULL, 'Eugene Hall', 0);
INSERT INTO public.autor VALUES (1231, 'Joanne "Jo" Murray, OBE (née Rowling), better known under the pen name J. K. Rowling, is a British author best known as the creator of the Harry Potter fantasy series, the idea for which was conceived whilst on a train trip from Manchester to London in 1990. The Potter books have gained worldwide attention, won multiple awards, sold more than 400 million copies, and been the basis for a popular series of films.', 'https://covers.openlibrary.org/a/olid/OL23919A-M.jpg', NULL, 'J. K. Rowling', 0);
INSERT INTO public.autor VALUES (1286, 'Jorge Mario Pedro Vargas Llosa (Arequipa, 28 de marzo de 1936-Lima, 13 de abril de 2025), conocido como Mario Vargas Llosa, fue un escritor peruano con nacionalidad española desde 1993 y nacionalidad dominicana desde junio de 2022. Considerado uno de los más importantes novelistas y ensayistas contemporáneos, sus obras cosecharon numerosos premios, entre los que destacan el Nobel de Literatura 2010, el Cervantes 1994 —considerado como el más importante en lengua española—, el Príncipe de Asturias de las Letras 1986, el Biblioteca Breve 1962, el Rómulo Gallegos 1967 y el Planeta 1993, entre otros. Como escritor, alcanzó la fama en la década de 1960 con novelas como *La ciudad y los perros* (1963), *La casa verde* (1966) y *Conversación en La Catedral* (1969). Continuó escribiendo prolíficamente en varios géneros literarios, como el ensayo, el artículo y el teatro. Entre sus novelas destacan asimismo *La guerra del fin del mundo* (1981), o *La fiesta del Chivo* (2000).INSERT INTO public.autor VALUES (1287, 'Jorge Francisco Isidoro Luis Borges (Buenos Aires, 24 de agosto de 1899 - Ginebra, 14 de junio de 1986), más conocido como Jorge Luis Borges, fue un destacado escritor de cuentos, poemas y ensayos argentino, extensamente considerado una figura clave tanto para la literatura en habla hispana como para la literatura universal. También fue bibliotecario, profesor, conferencista y traductor. Sus dos libros más conocidos, *Ficciones* y *El Aleph,* publicados en los años cuarenta, son recopilaciones de cuentos conectados por temas comunes de forma fantástica, como los sueños, los laberintos, las bibliotecas, los espejos, los autores ficticios y las mitologías europeas (como la griega y la nórdica), con argumentos que exploran ideas filosóficas relacionadas, por ejemplo, con la memoria, la eternidad, la posmodernidad y la metaficción. Las obras de Borges han contribuido ampliamente a la literatura filosófica, al género fantástico y al posestructuralismo. Según marcan numerosos críticos, el comienzo del realismo mágico en la literatura hispanoamericana del siglo XX se debe en gran parte a su obra.', 'https://covers.openlibrary.org/a/olid/OL18928A-M.jpg', NULL, 'Jorge Luis Borges', 0);
INSERT INTO public.autor VALUES (1288, 'José de Sousa Saramago, GColSE ComSE GColCa (Portuguese: [ʒuˈzɛ ðɨ ˈso(w).zɐ sɐɾɐˈmaɣu]; 16 November 1922 – 18 June 2010), was a Portuguese writer and recipient of the 1998 Nobel Prize in Literature for his "parables sustained by imagination, compassion and irony [with which he] continually enables us once again to apprehend an elusory reality." His works, some of which can be seen as allegories, commonly present subversive perspectives on historic events, emphasizing the theopoetic human factor. [source](https://en.wikipedia.org/wiki/Jos%C3%A9_Saramago)', 'https://covers.openlibrary.org/a/olid/OL3112635A-M.jpg', NULL, 'José Saramago', 0);
