INSERT INTO public.autor VALUES (1291, 'Albert Camus was a French Algerian author, philosopher, and journalist who was awarded the Nobel Prize for Literature in 1957. He was a key philosopher of the 20th-century and his most famous work is the novel *L''Étranger* (*The Stranger*).INSERT INTO public.autor VALUES (1292, 'Hermann Karl Hesse -pseudonym: Emil Sinclair- (* 2. Juli 1877 in Calw; † 9. August 1962 in Montagnola, Schweiz), war ein deutsch-schweizerischer Schriftsteller, Dichter und Maler. Bekanntheit erlangte er mit Prosawerken wie *Siddhartha, Demian, Der Steppenwolf* sowie auch *Narziß und Goldmund* und mit seinen Gedichten (z. B. *Stufen).* 1946 wurde ihm der Nobelpreis für Literatur und 1954 der Orden Pour le Mérite für Wissenschaften und Künste verliehen.INSERT INTO public.autor VALUES (1293, NULL, 'https://covers.openlibrary.org/a/olid/OL3872870A-M.jpg', NULL, 'James Kingsland', 0);
