INSERT INTO public.autor VALUES (1325, 'Frederik Pohl, Jr. was born in Brooklyn, New York.  His father held a number of jobs, and his family moved many times in his childhood before settling in Brooklyn when he was about seven.  He attended Brooklyn Tech high school, but dropped out and took a job to help support his family.  As a teen, he founded the New York science fiction writer''s group The Futurians.  His first publication, a poem, appeared in Amazing Stories in 1937, when he was 18 years old.  In 1936, he joined the Young Communist League and became President of the Brooklyn branch, but he left it in 1939 after Stalin-Hitler pact.  In 1939, at the age of 21, he was editor of both Super Science Stories and Astonishing Stories, and regularly published his own stories in both of them.  He married his first wife in 1940.  In 1943 both the magazines he was editing folded, and he worked as a literary agent.  During World War II, he served with the Army Air Corps from 1945-1945.  He divorced his first wife during this period and married his second wife in 1945.  In 1948 he married his third wife, Judith Merril, who he divorced in 1953, the same year he married his fourth wife, Carol Metcal Ulf.INSERT INTO public.autor VALUES (1326, NULL, 'https://covers.openlibrary.org/a/olid/OL1073715A-M.jpg', NULL, 'Dieter Wuckel', 0);
