INSERT INTO public.autor VALUES (1341, 'Miguel de Cervantes Saavedra was a Spanish novelist, poet, and playwright. His magnum opus, Don Quixote, often considered the first modern novel, is a classic of Western literature and is regularly regarded among the best novels ever written. His work is considered among the most important in all of literature. His influence on the Spanish language has been so great that Spanish is often called *la lengua de Cervantes* (The language of Cervantes). He has been dubbed *el Príncipe de los Ingenios* - the Prince of Wits. ([Source][1].)INSERT INTO public.autor VALUES (1342, NULL, 'https://covers.openlibrary.org/a/olid/OL13571507A-M.jpg', NULL, 'Antonio Fernández y Morales', 0);
