INSERT INTO public.autor VALUES (1385, 'Stephen Edwin King (born September 21, 1947) is an American author of horror, supernatural fiction, suspense, crime, science-fiction, and fantasy novels. His books have sold more than 350 million copies, and many have been adapted into films, television series, miniseries, and comic books. King has published 63 novels, including seven under the pen name Richard Bachman, and five non-fiction books. He has also written approximately 200 short stories, most of which have been published in book collections.INSERT INTO public.autor VALUES (1386, NULL, NULL, NULL, 'Edurne Brazal Goitia', 0);
