INSERT INTO public.autor VALUES (1463, 'Russian novelist Fyodor Mikhailovitch Dostoyevsky was a journalist and short-story writer, whose psychological penetration into the human soul profoundly influenced the 20th century novel. Dostoevsky''s novels have much autobiographical elements, but ultimately they deal with moral and philosophical questions. He presented interacting characters with contrasting views or ideas about freedom of choice, Socialism, atheisms, good and evil, happiness and so forth. Dostoevsky''s central obsession was God, whom his characters constantly search through painful errors and humiliations. ([Source](http://www.kirjasto.sci.fi/fdosto.htm))INSERT INTO public.autor VALUES (1465, NULL, NULL, NULL, 'Fidor Dostoievski', 0);
