INSERT INTO public.autor VALUES (1542, 'Mary Pope Osborne was born into adventure. Her dad was in the army, so every year or two her family would move to a different state, or even a different country! By the time she was fifteen, Mary had lived in thirteen different houses and gone to eight different schools!INSERT INTO public.autor VALUES (1543, NULL, 'https://covers.openlibrary.org/a/olid/OL4381768A-M.jpg', NULL, 'Joseph Sabin', 0);
