INSERT INTO public.libro VALUES (2114, 1891, 'Aliens', 'afcMAAAAYAAJ', NULL, 212, 'http://books.google.com/books/content?id=afcMAAAAYAAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'Los extranjeros: su admisión, su expulsión', 1413);
INSERT INTO public.libro VALUES (2035, 2013, 'Fiction', 'XVG2AwAAQBAJ', '9788490193884', 938, 'http://books.google.com/books/content?id=XVG2AwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Mistborn. Trilogía Original - Libro 3 Mistborn es la saga que ha convertido a Brandon Sanderson en el gran autor de fantasía del siglo XXI. Más de diez millones de ejemplares vendidos en todo el mundo. «Un mundo absolutamente fascinante.» The Washington Post El apasionante cierre de la Trilogía Mistborn. Vin cumplió la profecía y liberó el poder acumulado en el Pozo de la Ascensión. Sin embargo, todo resultó ser una trampa, y ahora el ser divino llamado Ruina campa a sus anchas por el mundo decidido a arrasarlo con terremotos y ríos de fuego. Tras haber esquivado la muerte convirtiéndose en un nacido de la bruma, el emperador Elend Venture confía en que las pistas que dejó el lord Legislador les sirvan para contraatacar. Las profecías hablan de un héroe, pero ¿no estaban corrompidas? Vin deberá desenmarañar la verdad para compensar su error. Solo así llegará a ser el Héroe de las Eras antes de que Ruina aniquile toda la vida sobre el planeta. La crítica ha dicho... «Brandon Sanderson es una leyenda.» Alexelcapo, @EvilAFM «Sanderson es un escritor brillante.» Patrick Rothfuss «Sanderson es una bomba a punto de explotar.» Ernest Alós, El Periódico de Catalunya «Si te gusta la literatura fantástica, lee a Brandon Sanderson.» Chicote «Hace tiempo que George R.R. Martin tiene heredero.» Javier Blánquez, El Mundo', 'El Héroe de las Eras (Trilogía Original Mistborn 3)', 1368);
INSERT INTO public.libro VALUES (2036, 2025, 'Comics & Graphic Novels', 'WnJg0QEACAAJ', '9788413149813', 0, 'http://books.google.com/books/content?id=WnJg0QEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 'Mistborn es la saga que ha convertido a Brandon Sanderson en el gran autor de fantasía del siglo XXI. Más de diez millones de ejemplares vendidos en todo el mundo. «Una de las mejores obras de fantasía jamás escrita.» - Forbes Las brumas gobiernan la noche. El lord Legislador domina el mundo. En otros tiempos, un héroe se alzó para salvar la humanidad. Fracasó. Desde entonces, el mundo es un erial de ceniza y niebla gobernado por un emperador inmortal conocido como el lord Legislador. Pero la esperanza perdura. Una nueva revuelta cobra forma cimentándose en la treta definitiva: la astucia de un brillante genio del crimen y la determinación de una heroína insólita, una joven ladrona callejera que deberá aprender a controlar el poder de los nacidos de la bruma. ENGLISH DESCRIPTION Now with over 10 million copies sold, The Mistborn Series has the thrills of a heist story, the twistiness of political intrigue, and the epic scale of a landmark fantasy saga. Once, a hero arose to save the world. He failed. Ever since, the world has been a wasteland of ash and mist controlled by the immortal emperor known as the Lord Ruler. But hope survives. A new uprising is forming, one built around the ultimate caper, the cunning of a brilliant criminal mastermind, and the determination of an unlikely heroine: a street urchin who must learn to master the power of a Mistborn.', 'Nacidos de la Bruma / Mistborn', 1368);
INSERT INTO public.libro VALUES (2037, 2015, 'Fiction', 'Y0WlAwAAQBAJ', '9788490197776', 449, 'http://books.google.com/books/content?id=Y0WlAwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Steelheart es el primer volumen de la elogiada «Trilogía de los Reckoners» de Brandon Sanderson, el autor de fantasía épica que más lectores está ganado en todo el mundo y que ya se ha convertido en el futuro heredero del trono de todo un género. Diez años atrás, Calamity irrumpió en la ciudad en la forma de una explosión en el cielo que otorgó a algunos seres poderes extraordinarios. A estos se los empezó a llamar Épicos, y pronto subyugaron a la población empleando sus increíbles poderes con el afán de gobernar la voluntad de los hombres y conquistar el mundo. Ahora, un tirano y furioso Épico llamado Steelheart se ha proclamado dueño y señor de la ciudad de Chicago Nova. De él se dice que es invencible; ninguna bala puede hacerle daño, ninguna espada puede atravesar su piel, ningún fuego quemar su cuerpo. Nadie se atreve a desafiarlo... Nadie salvo los Reckoners, un grupo clandestino que no goza de poderes pero sí de una férrea disciplina, conseguida tras pasarse la vida estudiando el comportamiento de los Épicos con el objetivo de hallar sus puntos débiles y poder así exterminarlos. El joven David Charleston se unirá a ellos con el fin de vengar la muerte de su padre a manos de Steelheart. El chico tiene una cualidad que le distingue del resto: sabe que el Épico no es invencible. David es el único que ha visto sangrar a Steelheart. Reseñas: «Brandon Sanderson es una leyenda.» Alexelcapo, @EvilAFM «Por desgracia para mi ego, Steelheart es otra victoria de Sanderson, con lo que demuestra no solo que es un brillante narrador de fantasía épica, sino que, rotundamente, es un escritor brillante.» Patrick Rothfuss, autor de El nombre del viento «Una aventura trepidante y llena de tensión. Brandon Sanderson es uno de los mejores escritores de fantasía y ciencia ficción que hay actualmente.» Christopher Paolini, autor de Eragon', 'Steelheart (Reckoners 1)', 1368);
INSERT INTO public.libro VALUES (2038, 2014, 'Forgers', 'o2XOoAEACAAJ', '9788415831204', 0, 'http://books.google.com/books/content?id=o2XOoAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 'Reunidos en un solo volumen, dos brillantes novelas cortas que ilustran sendas facetas de la obra de uno de los maestros consagrados de la fantasía contemporánea internacional, y que hacen gala tanto de su firme pulso narrativo como del alcance de su poderosa imaginación. Fantascy presenta un auténtico acontecimiento para los numerosos seguidores de Brandon Sanderson, y un descubrimiento para los que aún no lo son: reunidos en un solo volumen, dos brillantes novelas cortas que ilustran sendas facetas de la obra de uno de los maestros consagrados de la fantasía contemporánea internacional y que hacen gala tanto de su firme pulso narrativo como del alcance de su poderosa imaginación. LEGIÓN Stephen Leeds tiene una mente tan poderosa que roza lo sobrehumano y le permite repartirse entre una multitud de personalidades, entes imaginarias que solo él ve, que despliegan una diversidad de habilidades especializadas. Cuando contratan sus servicios para recuperar un objeto robado, Leeds se lanza a la búsqueda del inventor, desaparecido en condiciones sospechosas. El artefacto codiciado es una cámara fotográfica capaz de captar imágenes del pasado, cuyas propiedades podrían cambiar nuestra forma de entender la historia de la humanidad. La investigación sumirá a Leeds en un conflicto que lo llevará desde Estados Unidos hasta la antigua ciudad de Jerusalén. Esta intensa aventura detectivesca aborda temas como la naturaleza del tiempo, los usos potenciales de la tecnología y la complicada relación entre la política y la fe. «Debería ser del agrado de las legiones de fans de Sanderson y también le hará ganar nuevos aficionados.» Pat''s Fantasy Hotlist EL ALMA DEL EMPERADOR Shai, una maga Falsificadora, ha sido condenada a muerte; pero el consejo le ofrece su libertad a cambio de la mayor falsificación que pueda emprenderse: la del alma del emperador, en estado catatónico tras un atentado. Al adivinar las motivaciones de sus captores, Shai deduce que no sobrevivirá ni siquiera si logra cumplir el cometido. Así pues, trama formas de escapar del palacio a la vez que que se esfuerza en comprender hasta el límite de lo posible los entresijos de la personalidad del emperador. Aunque asume la necesidad de huir, a Shai le atrae poderosamente la idea de crear la falsificación más extraordinaria del mundo... ¿Es posible crear una copia de un alma tan convincente que supere al original? ENGLISH DESCRIPTION When Shai is caught replacing the Moon Scepter with her nearly flawless forgery, she must bargain for her life. An assassin has left the Emperor Ashravan without consciousness, a circumstance concealed only by the death of his wife. If the emperor does not emerge after his hundred-day mourning period, the rule of the Heritage Faction will be forfeit and the empire will fall into chaos. Shai is given an impossible task: to create--to Forge--a new soul for the emperor in less than one hundred days. But her soul-Forgery is considered an abomination by her captors. She is confined to a tiny, dirty chamber, guarded by a man who hates her, spied upon by politicians, and trapped behind a door sealed in her own blood. Shai''s only possible ally is the emperor''s most loyal counselor, Gaotona, who struggles to understand her true talent. Time is running out for Shai. Forging, while deducing the motivations of her captors, she needs a perfect plan to escape...', 'Legión y el alma del emperador', 1368);
INSERT INTO public.libro VALUES (2039, 2021, 'Fiction', 'NShJEAAAQBAJ', '9788417906702', 82, 'http://books.google.com/books/content?id=NShJEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Ambientado en el mismo universo que la serie Escuadrón, La defensa del Elíseo tiene lugar siglos antes de sus acontecimientos. Ganador del premio UPC de Ciencia Ficción Apareció en la revista Asimov''s Science Fiction «Le vino una imagen a la mente, la imagen de la humanidad escapando al espacio. Una imagen de comerciantes humanos negociando y estafando, de tiranos humanos dominando a las especies tecnológicamente inferiores, los varvax, los tenasi, los hommar. Imágenes de guerras, de conflicto, de un paraíso destruido». Curiosamente, quienes establecieron el Primer Contacto fueron los trabajadores de una compañía telefónica anticuada y casi en quiebra. Desde entonces, ante la inferioridad intelectual humana, la Compañía Telefónica ha sido la intermediaria entre los humanos y las poblaciones galácticas. Todo el mundo sospecha que dominan los viajes superlumínicos, pero nadie ha sido capaz de demostrarlo. Y ellos, por su parte, actúan bajo sus propias reglas, con independencia de las impuestas por los Gobiernos Unidos. Jason Write, un agente de la compañía, ha jurado mantener la galaxia a salvo de los bárbaros humanos que no harían otra cosa que arruinar el Elíseo del que las razas galácticas disfrutan actualmente. Sin embargo, cuando una colaboradora de la compañía desaparezca, los cimientos en los que se fundamentan todas sus creencias 3⁄4y sus sentidos3⁄4 empezarán a tambalearse. Desde 2006, Brandon Sanderson se ha consolidado como el gran renovador de la fantasía y de la ciencia ficción del siglo XXI. Ha logrado ganarse a veinte millones de lectores, publicar en treinta y cinco idiomas y convertirse en el heredero de todo un género Críticas: «Brandon Sanderson es una leyenda». Alexelcapo, @EvilAFM «Sanderson es un escritor brillante». Patrick Rothfuss «El renovador de la fantasía, el gran reinventor de la magia». Ricard Ruiz Garzón, Els Matins de TV3 «Sanderson es una bomba a punto de explotar». Ernest Alós, El Periódico de Catalunya «Si te gusta la literatura fantástica, lee a Brandon Sanderson». Chicote «Hace tiempo que George R.R. Martin tiene heredero». Javier Blánquez, El Mundo «Se hablará de Sanderson con la misma devoción que de Tolkien, Leiber, Moorcock, Jordan... y George R.R. Martin.» SFFWorld «Es raro que un autor de ficción comprenda tan bien cómo funciona el liderazgo y cómo el amor echa raíces en el corazón humano. Sanderson es sorprendentemente sabio.» Orson Scott Card', 'La defensa del Elíseo', 1368);
INSERT INTO public.libro VALUES (2040, 2023, 'Fiction', 'DDHFEAAAQBAJ', '9788419260031', 493, 'http://books.google.com/books/content?id=DDHFEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Brandon Sanderson añade a su universo del Cosmere (compartido por las sagas Nacidos de la Bruma y El Archivo de las Tormentas) una nueva novela independiente que hará las delicias de los aficionados a la cultura popular asiática. Yumi viene de una tierra de jardines, meditación y espíritus, mientras que Pintor vive en un mundo de oscuridad, tecnología y pesadillas. Cuando de pronto sus vidas se ven extrañamente entrelazadas, ¿podrán dejar de lado sus diferencias y colaborar para descubrir los misterios de su situación y salvar sus respectivas comunidades de un desastre seguro? Nota de Brandon: «Llevaba años queriendo escribir una novela de fantasía protagonizada por personas que hacen trabajos normales para ellas, pero fantásticos para nosotros como lectores. Además, mi esposa me animó a añadir más romanticismo a mis historias. Cuando junté a dos personas cuyo trabajo le parece fantástico al otro, nació el relato de Yumi y el pintor de pesadillas. Esta novela en particular fue un regalo especial para mi esposa, regalo que ambos estamos encantados de compartir ahora con vosotros.»', 'Yumi y el pintor de pesadillas', 1368);
INSERT INTO public.libro VALUES (2041, 2022, 'Comics & Graphic Novels', 'PzdlEAAAQBAJ', '9788418037566', 498, 'http://books.google.com/books/content?id=PzdlEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'La edición omnibus del debut de Brandon Sanderson en la novela gráfica. Con Arena blanca el autor estrella de la fantasía contemporánea convierte una adaptación de obra inédita ambientada en el Cosmere en una espectacular saga para todos los amantes de la fantasía, la aventura y el cómic. En el planeta Taldain, los legendarios maestros de arena poseen poderes arcanos que les confieren un control espectacular sobre el elemento del que toman su nombre. Pero cuando una siniestra conspiración se salda con su desaparición violenta, el más débil de ellos, Kenton, cree haber sido el único superviviente. Cercado por sus adversarios desde todos los frentes, Kenton forja una improbable alianza con Khriss, una misteriosa "ladoscura" que oculta sus propios secretos. Bienvenidos al emocionante libro cuya primera parte fue galardonada con el Premio Dragon 2018 a la mejor novela gráfica. Brandon Sanderson es el gran renovador de la fantasía del siglo XXI y el autor más prolífico del mundo, con más de veintidós millones de lectores en treinta lenguas.', 'Arena Blanca. Una novela gráfica del Cosmere (volúmenes 1-3)', 1368);
INSERT INTO public.libro VALUES (2042, 2023, 'Young Adult Fiction', 'uUDYEAAAQBAJ', '9788419260017', 536, 'http://books.google.com/books/content?id=uUDYEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'La última entrega de la saga Escuadrón: Una chica viajará más allá de las estrellas para salvar la destrucción del mundo. Spensa ha salido de la ninguna-parte, pero lo que vio en el espacio la ha cambiado para siempre. Se enfrentó a los zapadores y por fin obtuvo respuestas a las preguntas que se hacía sobre sus propios y extraños dones citónicos. Pero la Supremacía no ha desistido en su lucha por el dominio galáctico mientras ella no estaba. El equipo de Spensa, el Escuadrón Cielo, logró resistir ante Winzik y hasta sumar aliados a su causa, pero es cuestión de tiempo que la humanidad y el resto de la galaxia caigan. Derrotar a sus enemigos pondrá a prueba todo el conocimiento que Spensa reunió en la ninguna-parte. En este libro final de la saga, la humanidad se liberará o caerá para siempre.', 'Desafiante (Escuadrón 4)', 1368);
INSERT INTO public.libro VALUES (2118, 1879, 'Capital punishment', 'ajKrNcmbmt8C', NULL, 62, 'http://books.google.com/books/content?id=ajKrNcmbmt8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'La pena de muerte y su aplicación en España', 1416);
INSERT INTO public.libro VALUES (2043, 2022, 'Literary Collections', 'ed1WEAAAQBAJ', '9788466671903', 331, 'http://books.google.com/books/content?id=ed1WEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'El curso de escritura creativa que Brandon Sanderson lleva casi dos décadas impartiendo en la universidad, por primera vez en formato libro. Curso de escritura creativa convierte en libro las clases que Brandon Sanderson lleva 16 años impartiendo anualmente en la Universidad Brigham Young, donde estudió. Él mismo dice que nunca ha dejado de darlas porque es un recurso que necesita para seguir creciendo como escritor. El curso se centra en los engranajes de la escritura y tiene un enfoque muy práctico; en él nos habla de la trama, la ambientación y los personajes, pero también de la parte empresarial. Sin embargo, no hace falta querer ser un escritor profesional para leer este libro. Su objetivo es ayudar a cualquier lector a comunicarse mejor y crear buenos hábitos para escribir de forma consistente, con los valiosos consejos de uno de los mayores creadores de nuestro siglo. «Os animo a que utilicéis este curso del modo que más os ayude a lograr vuestros objetivos.» Brandon Sanderson', 'Curso de escritura creativa', 1368);
INSERT INTO public.libro VALUES (2044, 2023, 'Fiction', 'xn3aEAAAQBAJ', '9788419260130', 496, 'http://books.google.com/books/content?id=xn3aEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Brandon Sanderson, el gran autor de fantasía del siglo XXI, nos lleva a un futuro de su universo del Cosmere en el que un perpetuo vagabundo planetario deberá decidir si seguir huyendo o quedarse y ayudar en un mundo atribulado. El Hombre Iluminado es una de las cuatro increíbles novelas con las que Sanderson ha protagonizado la mayor campaña de micromecenazgo de la historia de Kickstarter. Hace años tenía compañeros de armas y una causa en la que creer, pero ahora el hombre que se hace llamar Nómada solo conoce la vida a la fuga. Obligado a saltar de un mundo a otro en el Cosmere cada vez que la implacable Brigada Nocturna le gana demasiado terreno, Nómada acaba en un nuevo planeta y de inmediato se ve implicado en la trifulca entre un tirano y los rebeldes que solo pretenden evitar que los conviertan en esclavos sin mente. Y todo bajo la amenaza constante de un amanecer cuyo calor derrite la misma piedra. Incapaz de comprender su idioma, ¿sabrá navegar el conflicto y obtener el suficiente poder para saltar fuera del planeta antes de que su mente o su cuerpo paguen el precio definitivo?', 'El Hombre Iluminado', 1368);
INSERT INTO public.libro VALUES (2045, 2026, 'Fiction', '46jEEQAAQBAJ', '9788410466449', 810, 'http://books.google.com/books/content?id=46jEEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Nueva edición de El aliento de los dioses, una rara avis del Cosmere, con las ilustraciones a color de la edición de piel de Dragonsteel. EL GRAN AUTOR DE FANTASÍA DEL SIGLO XXI. MÁS DE 50 MILLONES DE LECTORES. Hace años, el monarca de Idris firmó un tratado con el reino de Hallandren según el cual el rey Dedelin enviaría a su hija mayor, Vivenna, para casarse con Susebron, el rey-dios de Hallabdren. Vivenna ha sido adiestrada durante toda su vida para ser una novia adecuada para Susebron y así cumplir con su deber y ayudar a forjar una paz estable entre los dos reinos. Ese era el plan, pero el monarca de Idris envía a su hija Siri, desobediente e independiente, en lugar de Vivenna. Mientras intenta encontrar su lugar en la corte de Susebron, Siri descubre la verdad oculta sobre el rey-dios. En Idris, Vivenna se siente intranquila y teme que su hermana no esté preparada para esa nueva vida, por lo que decide viajar a Hallandren. Allí se reúne con la gente de Idris que trabaja en la capital, Telir, y comienza una nueva vida de espionaje y sabotaje. El plan de Vivenna es rescatar a Siri, aunque tal vez esta ni necesite ni desee ser salvada.', 'El aliento de los dioses (edición ilustrada)', 1368);
INSERT INTO public.libro VALUES (2046, 2022, 'Young Adult Fiction', 'InxvEAAAQBAJ', '9788418037764', 836, 'http://books.google.com/books/content?id=InxvEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'La colección de novelas cortas de la saga de fantasía estelar «Escuadrón». Este volumen incluye ilustraciones exclusivas de los personajes y las escenas eliminadas con comentarios de Brandon Sanderson. Incluye La defensa del Elíseo. Viajamos con el Escuadrón Cielo a Detritus, el último refugio de la humanidad frente al gobierno hostil de la Supremacía Galáctica. En Escuadrón, Spensa Nitghshade se convirtió en piloto de caza estelar y pasó a formar parte del Escuadrón Cielo de la Fuerza de Defensa Desafiante con el objetivo de combatir la amenaza de la Supremacía. En Estelar, se hizo pasar por la alienígena Alanik para infiltrarse en una estación espacial de la Supremacía y robar sus hipermotores. Y en Citónica viajó a la extraña dimensión conocida como la ninguna-parte para descubrir los secretos de los zapadores -unos seres capaces de destruir planetas enteros- y liberar sus propios poderes citónicos. Mientras Spensa está atrapada en la ninguna-parte, sus compañeros de escuadrón, FM y Jorgen permanecen en Detritus con nuevas órdenes: averiguar cómo utilizar los hipermotores para que la humanidad pueda huir del planeta y buscar aliados entre las otras especies oprimidas por la Supremacía. Primeror reciben una llamada de emergencia de le ministre Cuna y otres diones desde el puesto de avanzada abandonado de Alcance Solar, pero el pueblo de Alanik en el planeta ReAlba y los kitsen del planeta Orilla Perpetua necesitarán también la ayuda del Escuadrón Cielo en sus desesperadas batallas.', 'Escuadrón Cielo: La colección', 1368);
INSERT INTO public.libro VALUES (2047, 2012, 'Fiction', 'y584AwAAQBAJ', '9788415389880', 787, 'http://books.google.com/books/content?id=y584AwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'El aliento de los dioses o Warbreaker, segunda novela de Brandon Sanderson, es una rara avis en la fantasía épica: una narración completa en un único volumen, con toda la imaginación, la aventura, la magia y los entrañables personajes a los que este autor, destinado a heredar el trono de todo un género, nos tiene acostumbrados. Hace años, el monarca de Idris firmó un tratado con el reino de Hallandren según el cual el rey Dedelin enviaría a su hija mayor, Vivenna, para casarse con Susebron, el rey-dios de Hallabdren. Vivenna ha sido adiestrada durante toda su vida para ser una novia adecuada para Susebron y así cumplir con su deber y ayudar a forjar una paz estable entre los dos reinos. Ese era el plan, pero el monarca de Idris envía a su hija Siri, desobediente e independiente, en lugar de Vivenna. Mientras intenta encontrar su lugar en la corte de Susebron, Siri descubre la verdad oculta sobre el rey-dios. En Idris, Vivenna se siente intranquila y teme que su hermana no esté preparada para esa nueva vida, por lo que decide viajar a Hallandren. Allí se reúne con la gente de Idris que trabaja en la capital, Telir, y comienza una nueva vida de espionaje y sabotaje. El plan de Vivenna es rescatar a Siri, aunque tal vez esta ni necesite ni desee ser salvada. Reseñas: «Brandon Sanderson es una leyenda.» Alexelcapo, @EvilAFM «Sanderson no es solo un gran y prolífico autor; es también alguien que, amando la fantasía, sabe que debe ser renovada y que debe ser repensada para encarar con éxito el siglo XXI.» Miquel Barceló, autor de Ciencia ficción. Nueva guía de lectura «Brandon Sanderson es una bomba a punto de estallar.» Ernest Alós, El Periódico de Catalunya', 'El aliento de los Dioses', 1368);
INSERT INTO public.libro VALUES (2146, 1860, 'Ficción', 'JoU0FlHN4sIC', NULL, 552, 'http://books.google.com/books/content?id=JoU0FlHN4sIC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'Tesoro de Oratoria Sagrada', 1430);
INSERT INTO public.libro VALUES (2048, 2020, 'Young Adult Fiction', 'u_zDDwAAQBAJ', '9788417347765', 542, 'http://books.google.com/books/content?id=u_zDDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'La continuación de Escuadrón, la saga épica de Brandon Sanderson. Este es el segundo libro de una serie épica sobre una chica que guarda un secreto en un peligroso mundo en guerra por el futuro de la humanidad. En él continúan las aventuras de Spensa Nightshade, la joven piloto que ha conseguido un puesto en el escuadrón de defensa de la humanidad contra los ataques alienígenas. En realidad, ella siempre quiso ser piloto: poder probar que es una heroína, como su padre. Y aunque llegó a lo más alto, los secretos que desenmascaró sobre su padre fueron aplastantes. Los rumores sobre su cobardía resultaron ciertos. Abandonó su vuelo durante la batalla contra los Krell. Peor aún... se volvió contra su equipo y los atacó. Sin embargo, Spensa está segura de que hay aún más por descubrir en esa historia. Y, si es necesario, viajará hasta el fin de la galaxia para salvar a la humanidad. Sobre Estelar: «Un poco de Perdidos en el espacio, un poco de Halo, un poco de The Expanse y mucho de Sanderson. Una novela que nos deja con muchas preguntas.» Alexelcapo, @EvilAFM', 'Estelar (Escuadrón 2)', 1368);
INSERT INTO public.libro VALUES (2049, 2019, 'Fiction', '0SGzDwAAQBAJ', '9788417347697', 404, 'http://books.google.com/books/content?id=0SGzDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Tres novelas cortas y cohesionadas que tienen la psicología como superpoder. Por el gran autor de fantasía del siglo XXI. Brandon Sanderson recopila en este libro las novelas cortas protagonizadas por Stephen Leeds, una interesantísima mezcla de ciencia ficción y suspense que incluye dos historias inéditas en castellano hasta la fecha. Stephen Leeds es un genio perfectamente cuerdo con alucinaciones alocadas. Es capaz de aprender cualquier nueva habilidad en cuestión de horas, pero para ello su mente necesita crear personas imaginarias a las que él llama "aspectos". Allá adonde va, se le une un equipo de expertos imaginarios que él usa para resolver problemas. Pero, de pronto, su cerebro roza el colapso cuando los "aspectos" empiezan a cobrar vida. Una empresa lo contrata para recuperar una propiedad robada, y Stephen termina atravesando océanos y luchando contra terroristas. Lo que descubre puede alterar los cimientos de las tres religiones más importantes del mundo y, tal vez, darle una pista clave sobre la verdadera naturaleza de sus alucinaciones. Legión: Las múltiples vidas de Stephen Leeds incluye Legión y, por primera vez en castellano, Legión: A flor de piel y el impactante final de la historia de Stephen Leeds, Las mentiras del contemplador. La crítica ha dicho: «Una lectura absolutamente maravillosa.» Fantasy Book Review', 'Legión: Las múltiples vidas de Stephen Leeds', 1368);
INSERT INTO public.libro VALUES (2050, 2025, 'Fiction', 'FXAb0QEACAAJ', '9788419260673', 0, 'http://books.google.com/books/content?id=FXAb0QEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 'Nueva edición de Sombras de identidad, una novela de Mistborn y el segundo volumen de Wax & Wayne, con 6 ilustraciones a color. Mistborn es la saga que ha convertido a Brandon Sanderson en el gran autor de fantasía del siglo XXI. Más de diez millones de ejemplares vendidos en todo el mundo. La segunda era continúa con una intriga política llena de magia. Waxillium Ladrian y su socio Wayne se enfrentan a una enemiga inaudita tras el brutal asesinato del hermano del gobernador, una kandra rebelde que ha perdido el juicio y ya no obedece al nuevo dios de Scadrial, Armonía. Mientras Wayne y Marasi intentan frustrar las amenazas contra el gobernador y evitar que la ciudad estalle en revueltas multitudinarias, Wax da caza a una asesina capaz de utilizar cualquier poder y de hacerse pasar por cualquiera. Pero él mismo se verá perseguido por las sombras de su pasado...', 'Sombras de Identidad (ed. Ilustrada) (wax and Wayne: Edición Ilustrada 2) / Shadows of Self', 1368);
INSERT INTO public.libro VALUES (2051, 2021, 'Fiction', 'LF-REAAAQBAJ', '9788417347932', 0, 'http://books.google.com/books/content?id=LF-REAAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 'La esperada continuación de Juramentada. Brandon Sanderson, en la cima de su carrera. Tras forjar una coalición de resistencia humana contra la invasión enemiga, Dalinar Kholin y sus Caballeros Radiantes llevan un año librando una guerra prolongada y brutal. Ningún bando ha logrado obtener ventaja. Mientras los nuevos descubrimientos tecnológicos cambian el trasfondo de la contienda, el enemigo prepara una operación audaz y peligrosa. La carrera armamentística resultante desafiará el mismo núcleo de los ideales Radiantes y quizá revele los secretos de la antiquísima torre en la que una vez residió toda su fuerza. ENGLISH DESCRIPTION The Stormlight Archive saga continues in Rhythm of War, the eagerly awaited sequel to Brandon Sanderson''s #1 New York Times bestselling Oathbringer, from an epic fantasy writer at the top of his game. After forming a coalition of human resistance against the enemy invasion, Dalinar Kholin and his Knights Radiant have spent a year fighting a protracted, brutal war. Neither side has gained an advantage, and the threat of a betrayal by Dalinar’s crafty ally Taravangian looms over every strategic move. Now, as new technological discoveries by Navani Kholin’s scholars begin to change the face of the war, the enemy prepares a bold and dangerous operation. The arms race that follows will challenge the very core of the Radiant ideals, and potentially reveal the secrets of the ancient tower that was once the heart of their strength. At the same time that Kaladin Stormblessed must come to grips with his changing role within the Knights Radiant, his Windrunners face their own problem: As more and more deadly enemy Fused awaken to wage war, no more honorspren are willing to bond with humans to increase the number of Radiants. Adolin and Shallan must lead the coalition’s envoy to the honorspren stronghold of Lasting Integrity and either convince the spren to join the cause against the evil god Odium, or personally face the storm of failure.', 'El ritmo de la guerra / Rhythm of War', 1368);
INSERT INTO public.libro VALUES (2052, 2018, 'Fiction', '7VhSDwAAQBAJ', '9788416628353', 94, 'http://books.google.com/books/content?id=7VhSDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Ahora en Flash, el maestro de la fantasía contemporánea internacional, Brandon Sanderson. Pasen y disfruten con Legión, el primero de los relatos dedicados al investigador Stephen Leeds. Stephen Leeds tiene una mente tan poderosa que roza lo sobrehumano y le permite repartirse entre una multitud de personalidades, entes imaginarias que solo él ve, que despliegan una diversidad de habilidades especializadas. Cuando contratan sus servicios para recuperar un objeto robado, Leeds se lanza a la búsqueda del inventor, desaparecido en condiciones sospechosas. El artefacto codiciado es una cámara fotográfica capaz de captar imágenes del pasado, cuyas propiedades podrían cambiar nuestra forma de entender la historia de la humanidad. La investigación sumirá a Leeds en un conflicto que lo llevará desde Estados Unidos hasta la antigua ciudad de Jerusalén. Esta intensa aventura detectivesca aborda temas como la naturaleza del tiempo, los usos potenciales de la tecnología y la complicada relación entre la política y la fe. Reseñas: «Brandon Sanderson es una leyenda.» Alexelcapo, @EvilAFM', 'Legión (Flash Relatos)', 1368);
INSERT INTO public.libro VALUES (2158, 1897, 'Ficción', 'hEy-XGMakS4C', NULL, 708, 'http://books.google.com/books/content?id=hEy-XGMakS4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'Catalogue of Printed Books', 1441);
INSERT INTO public.libro VALUES (2159, 1874, 'Ficción', 'Z_L3HKATCUAC', NULL, 736, 'http://books.google.com/books/content?id=Z_L3HKATCUAC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'Catalogue of the Library of the Boston Athenaeum', 1318);
INSERT INTO public.libro VALUES (2054, 2020, 'Fiction', 'iGwZEAAAQBAJ', '9780593311226', 713, 'http://books.google.com/books/content?id=iGwZEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Una fascinante historia sobre de la lucha entre el bien y el mal, en un mundo en donde los buenos no siempre ganan. En mitad de la noche en un barrio tranquilo de Minneapolis raptan a Luke Ellis, de doce años, tras haber asesinado a sus padres. Una operación que dura menos de dos minutos. Luke se despierta en E Instituto, en un cuarto exactamente igual que el suyo pero sin ventanas. En habitaciones parecidas hay más niños: Kalisha, Nick, George, Iris y Avery Dixon, entre otros, que comparten capacidades especiales como la telequinesia o la telepatía. Todos ellos se alojan en la Mitad Delantera de la institución. Los mayores, en cambio, se encuentran en la Mitad Trasera. Como dice Kalisha: "El que entra no sale". En este instituto tan siniestro, la directora la Señora Sigsby y sus empleados, se dedican a extraer la fuerza supernatural de cada uno de los niños, siempre de una manera despiadada y sin escrúpulos. Si los niños cooperan, ganan monedas para las máquinas de dulces. Pero si no, el castigo es brutal. Cada vez que una víctima desaparece, Luke se encuentra más desesperado por escapar y buscar ayuda. Pero nunca nadie ha logrado escapar del Instituto "Bajo los fuegos artificiales de su imaginación incansable, Stephen King nos muestra en sus mejores novelas que lo raro, lo extraordinario, lo verdaderamente insólito es vivir". --El Mundo', 'El instituto', 1245);
INSERT INTO public.libro VALUES (2055, 2022, 'Biography & Autobiography', 'bkVzEAAAQBAJ', '9788728331040', 234, 'http://books.google.com/books/content?id=bkVzEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Interesante experimento que convierte en ficción los primeros años de la biografía del afamado escritor Stephen King. Claudio Hernández, uno de los principales expertos de España en su obra, nos presenta los albores de la carrera que cambiaría para siempre la ficción de terror en todo el mundo, desde los primeros relatos a las cartas de rechazo que el escritor acumulaba una tras otra, clavadas en un clavo en su pared, hasta conseguir por fin un éxito apabullante con su primera novela: Carrie. Claudio Hernández es un autor español especializado en terror, thriller y fantasía. Muy influenciado por Stephen King desde pequeño, ha llegado a escribir una biografía sobre sus primeros años como escritor. En la actualidad se dedica por entero a la ficción de género, en especial de terror. Ha publicado numerosos libros que le han valido un gran éxito tanto de crítica como de público.', 'Los inicios de Stephen King', 1371);
INSERT INTO public.libro VALUES (2056, 2024, 'Fiction', '5GD4EAAAQBAJ', '9788410183094', 254, 'http://books.google.com/books/content?id=5GD4EAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', '¿Somos dueños de nuestro destino? Un oscuro e inquietante thriller en torno al libre albedrío. Terror y género policiaco combinados en una adictiva novela en la línea del maestro John Connolly. Cuando, como las tímidas gotas que anticipan la furia de la tormenta, los cadáveres de varios gatos sacrificados comienzan a salpicar la ciudad de Sevilla, dos detectives sacados de su letargo por los macabros sucesos se verán enfrentados de improviso a una serie de extraños acontecimientos y, sobre todo, a una cuestión de siempre esquiva naturaleza. Desde Aristóteles hasta Einstein, desde Calderón de la Barca a Simon Laplace, muchos han sido quienes a lo largo de los siglos han intentado dar respuesta a uno de los grandes interrogantes de la historia de la humanidad: ¿es el hombre realmente libre o existe un sendero ya trazado que recorremos sin saberlo? En este oscuro e inquietante thriller en torno al libre albedrío, se ofrecen algunas respuestas, tan válidas como cualquier otras, pero, sobre todo, se arrojan, como dardos de sombra, muchas inquietantes preguntas.', 'El demonio de Laplace', 1372);
INSERT INTO public.libro VALUES (2057, 2017, 'Performing Arts', 'DUwuDwAAQBAJ', '9788491341895', 922, 'http://books.google.com/books/content?id=DUwuDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', '¿De qué tienes miedo? Del dolor, de la muerte, de la pérdida... La mayoría de nuestros terrores son innatos, espontáneos, pero también pueden ser aprendidos, sociales, colectivos. Hemos aprendido a temer muchas cosas en lo que va de siglo, empezando por los atentados del 11 de septiembre y siguiendo con la crisis financiera. Este volumen se centra en el cine de terror estadounidense estrenado entre el 11-S y el comienzo de la crisis (2001-2011), para analizar los cambios que se han producido en la ideología dominante. A través del terror, los excesos del orden y las amenazas de la otredad se vuelven transparentes, pero para verlos debemos elucidar la relación entre el cine y la ideología, entre nuestros miedos cotidianos y los de la ficción. Desde una perspectiva teórica y analítica, este libro analiza con rigor cómo el cine de terror dialoga con la ideología de nuestra época.', 'Noche sobre América', 1373);
INSERT INTO public.libro VALUES (2058, 2022, 'Art', 'j7WHEAAAQBAJ', '9788499176864', 79, 'http://books.google.com/books/content?id=j7WHEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Una guía de las películas, canciones, juegos, series de TV y cómics que te hicieron soñar y que inspiraron a la famosa serie Casi nada en "Stranger Things" sucede por azar. Todo parece estar ahí por algún motivo. A veces es más evidente, y otras menos. Sucede que incluso puede estar profundamente oculto, como ese demogorgon que surge de las entrañas del pequeño pueblo de Hawkins. La lista de guiños a los años ochenta que los creadores de la serie han incrustado es infinita. Pero está hecha con un objetivo: seducir por igual a jóvenes y adultos. Quienes hayan crecido con "ET" o "Los Goonies" o hayan escuchado infinitas veces en su reproductor «Every Breath You Take» de Police pensarán, viendo la serie, que se hallan en un carrusel que gira hacia épocas pretéritas. Y así es. Este libro trata de echar un poco de luz sobre una serie que no habla más que de aventuras y monstruos pero que está construida con algunos de los mejores referentes del cine y la televisión de los años ochenta. Destila amor por un modo de narrar historias propias de una época y recordarlas con una pizca de nostalgia nos acerca más a la felicidad. * Un homenaje al cine de Steven Spielberg, Stanley Kubrick, Ridley Scott, John Carpenter. * De Peter Gabriel a Cyndi Lauper: la banda sonora de una generación. * Videojuegos: El auge de las salas recreativas. * De Stephen King a Lovecraft y Tolkien. * Gofres, bicicletas y Farrah Fawcett. * El proyecto MK Ultra o cómo controlar la mente mediante drogas psicodélicas.', 'A través de Stranger Things', 1374);
INSERT INTO public.libro VALUES (2102, 2007, 'Business & Economics', 'lc9iA9JOAhEC', '9789702605270', 756, 'http://books.google.com/books/content?id=lc9iA9JOAhEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'CONTENIDO: Fundamentos de negocios internacionales - Ambientes culturales que enfrentan las empresas - Los ambientes políticos y legales que enfrentan los negocios - El contexto económico - Teoría del comercio internacional - Influencia gubernamental en el comercio - Integración económica regional y acuerdos de cooperación - Movilidad de los recursos e investigación extranjera directa - El mercado de divisas - La determinación de los tipos de cambio - Actitudes gubernamentales hacia la inversión extranjera directa - Negociaciones diplomacia en los negocios internacionales - Evaluación de selección de países - Estrategias de colaboración - Estrategias de control - Marketing - Estrategias de importación y exportación - Manufactura global y gestión de la cadena de abasto - Funciones contables y fiscales multinacionales - La función financiera multinacional - Gerencia de recursos humanos.', 'Negocios internacionales', 1407);
INSERT INTO public.libro VALUES (2059, 2019, 'Performing Arts', 'Nh2EDwAAQBAJ', '9788417338923', 224, 'http://books.google.com/books/content?id=Nh2EDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Llega la guía ilustrada oficial de la serie de Netflix más ochentera y exitosa de todos los tiempos. Stranger Things. Mundos del revés es la guía oficial y el compañero perfecto para adentrarse detrás de las cámaras de Stranger Things. Presentado por los hermanos Duffer, creadores de la serie, este libro nos ofrece material inédito y exclusivo para entender y descubrir los secretos de la serie mediante mapas y entrevistas con los actores. El cuidado diseño a todo color pretende imitar un clásico libro de suspense de los años 80. Nos introduciremos en el proceso creativo de los Duffer de la mano de todo el equipo y haremos una profunda inmersión en la cultura y las referencias que inspiraron el ambiente ochentero de la serie. Con referencias constantes a las dos primeras temporadas y algunas pistas sobre el futuro de la serie... «Este libro es para ti, por haberte unido a nosotros en este viaje y por continuar inspirándonos... y también para todos aquellos que se ganan la vida soñando o que sueñan con hacerlo. Porque este mundo necesita más creadores de historias. Necesita más soñadores.» Matt y Ross Duffer', 'Stranger Things. Mundos del revés', 1375);
INSERT INTO public.libro VALUES (2060, 2026, 'Fiction', 'PdnQEQAAQBAJ', '9791388220081', 262, 'http://books.google.com/books/content?id=PdnQEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Dentro del archivo de Stephen King. Así nacieron los miedos que marcaron a millones de lectores. Una exploración fascinante y sin precedentes del universo de Stephen King y los cinco libros más icónicos de los inicios de su carrera Caroline Bicks, catedrática Stephen E. King de Literatura de la Universidad de Maine, fue también la primera investigadora a la que King concedió acceso prolongado a sus archivos personales: un tesoro de manuscritos, borradores y anotaciones nunca antes estudiados. A partir del análisis de cinco obras emblemáticas — El resplandor, Carrie, Cementerio de animales, Salem''s Lot y El umbral de la noche —, Bicks revela cómo King construyó su lenguaje, sus tramas y sus personajes, y saca a la luz escenas y finales alternativos autorizados por el autor. A medio camino entre la clase magistral, la biografía y el memoir, Monstruos en el archivo ofrece un acceso único al taller creativo del maestro del terror.', 'Monstruos en el archivo', 1376);
INSERT INTO public.libro VALUES (2061, 2006, 'Spain', 'zx8B1ScewgEC', NULL, 1296, 'http://books.google.com/books/content?id=zx8B1ScewgEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', NULL, 'Bibliografía española', 1318);
INSERT INTO public.libro VALUES (2062, 2020, 'Juvenile Fiction', 'K5TQEAAAQBAJ', '9788418259265', 216, 'http://books.google.com/books/content?id=K5TQEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Riverdale: sal de este pueblo, la novela imprecindible para los fanáticos de la serie. Esta es tu oportunidad de conocer más sobre Archie, Veronica, Betty y Jughead. Archie está enfrentando un juicio por asesinato y las pruebas van en su contra. Betty, Veronica y Jughead saben que todo ese juicio está orquestado por Hiram Lodge, pero... ¿cómo pueden demostrarlo? Pero a último momento, se les ocurre una idea que podría demostrar la inocencia de Archie: deben regresar a la escena del crimen. Tienen que regresar a Shadow Lake. Las amenazas se esconden detrás de cada árbol del bosque en la finca de familia Lodge. ¿Podrán Betty, Veronica y Jughead limpiar el nombre de Archie? Y más importante aún, ¿podrán regresar a Riverdale con vida?', 'Riverdale', 1377);
INSERT INTO public.libro VALUES (2063, 2010, 'Language Arts & Disciplines', 'C_7PCwAAQBAJ', '9788497880848', 226, 'http://books.google.com/books/content?id=C_7PCwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Cuando se habla de comunicación escrita se tiene que hablar de escritura eficaz. Y esto significa que el escritor logre de su público lo que se había propuesto: informarle, orientarle, hacerle pensar, proporcionarle una opinión, emocionarle o convencerle. En resumidas cuentas, para que se oiga su voz entre tanto griterío hay que acumular seducción y que la escritura sea fundamentalmente sexy. En este libro me propongo darle pistas para que usted escriba de manera atractiva.', 'Escritura sexy', 1378);
INSERT INTO public.libro VALUES (2064, 2006, 'Ficción', 'mXobAQAAIAAJ', NULL, 484, 'http://books.google.com/books/content?id=mXobAQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', NULL, 'Cuentos de horror', 1318);
INSERT INTO public.libro VALUES (2065, 2024, 'Fiction', 'Fz0qEQAAQBAJ', '9788408298175', 340, 'http://books.google.com/books/content?id=Fz0qEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', '«Todo parecía ir bien, pero Blanca sabía que nada iba bien en realidad». Una novela generacional, fresca y mordaz. Una mañana de 1993, la vida de Blanca se rompe cuando su padre le anuncia que su madre no regresará. A partir de entonces, Blanca teme que pueda tener un don insólito: la capacidad de obrar milagros, aunque el primero sea provocar la muerte de una niña que se burla de su situación familiar. Con el peso de la culpa sobre sus hombros y las ansiedades propias del abandono, Blanca busca en internet personas con las que hablar y conecta con un grupo de chicas que también se encuentran solas y perdidas. Unidas por la fascinación que sienten por Charles y Marilyn Manson, Joy Division y su gusto por vestir de negro, Blanca encuentra en ellas a su familia elegida. Fuego en la garganta recorre la infancia y la adolescencia de una chica que no encuentra su lugar en el mundo. Una aventura que se trasladará de las pantallas a un mundo real en el que habitan padres ausentes, héroes inesperados, monjas, tecnófobos y jipis del sur de España.', 'Fuego en la garganta', 1379);
INSERT INTO public.libro VALUES (2066, 2020, 'Biography & Autobiography', 'p7QEEAAAQBAJ', '9788418235344', 45, 'http://books.google.com/books/content?id=p7QEEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', '¿Autobiografía? ¿Ensayo? A lo largo de este texto rebosante de sinceridad, el lector conocerá el testimonio directo y la opinión de su autor sobre un tema que aún a día de hoy sigue ocasionando algún que otro conflicto en la sociedad y en muchas familias: salir del armario.', 'Amar u odiar: esa es la cuestión', 1380);
INSERT INTO public.libro VALUES (2067, 2024, 'Literary Criticism', 'jIbzEAAAQBAJ', '9788411002561', 676, 'http://books.google.com/books/content?id=jIbzEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'El universo literario en una cáscara de nuez ¿Has perdido el hábito de leer por placer? ¿Hay libros que crees que deberías conocer, pero te parecen demasiado complicados? Cómo ser culto es la guía de referencia para disfrutar de las mejores historias. A través de relatos breves y entretenidos sobre cinco géneros literarios –ficción, autobiografía, historia, teatro, y ciencia–, Susan Wise Bauer comparte su pasión por los clásicos y demuestra que cualquiera puede disfrutar de la obra maestra de Cervantes, los sonetos de Shakespeare o las novelas de Jane Austen. Este libro te enseñará a dedicarle tiempo a la lectura, dominar un argumento complejo, emitir juicios personales y literarios sobre lo que lees y apreciar los vínculos resonantes entre textos. Una obra que, de forma amena, concentra toda la sabiduría del curso de literatura universal que siempre quisiste hacer y nunca te dio tiempo.', 'Cómo ser culto', 1381);
INSERT INTO public.libro VALUES (2068, 1998, 'Argentine literature', 'rULtAAAAMAAJ', NULL, 340, 'http://books.google.com/books/content?id=rULtAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', NULL, 'León en el bidet', 1318);
INSERT INTO public.libro VALUES (2069, 2025, 'Fiction', 'swBdEQAAQBAJ', '9788423368143', 335, 'http://books.google.com/books/content?id=swBdEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'La primera novela de J. D. Barker, autor de El Cuarto Mono. Terror clásico e intriga con el estilo único del maestro americano del suspense. Cuando Thad McAlister, un joven y exitoso autor de bestsellers de terror, empieza a escribir su nueva novela, siente que las palabras fluyen sin esfuerzo. La historia, arraigada en los juicios de brujas de siglos pasados, parece avanzar sola y Thad llena una página tras otra de aterradores personajes, probablemente los más terroríficos que haya escrito jamás. Está exultante y convencido de que su nuevo libro es su gran obra maestra. Pero poco a poco también crece un miedo en su interior, pues siente que a su alrededor ocurre algo extraño. ¿Es realmente ficción todo lo que escribe? Lo que Thad todavía no sabe es que, involuntariamente, ha abierto una puerta al pasado que pronto pondrá en peligro su vida y la de su familia. Mientras tanto, en su casa, su mujer se pregunta en secreto si, quizá, ella es la culpable de todo lo que está ocurriendo por un oscuro trato que hizo mucho tiempo atrás. Finalista del premio Bram Stoker, ganadora del premio New Apple Medalist y nominada a mejor novela de terror en Goodreads, Las abandonadas es la novela con la que debutó J. D. Barker despertando la admiración de crítica y lectores. Una novela adictiva, brillante e ingeniosa.', 'Las abandonadas', 1382);
INSERT INTO public.libro VALUES (2070, 2018, 'Juvenile Fiction', 'MQdTDwAAQBAJ', '9788427044562', 215, 'http://books.google.com/books/content?id=MQdTDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', '... pero el corazón es algo que no puedo controlar. Wendy, Adriel, Eric, Alicia, Paula, Rubén... Todos ellos son los protagonistas de un relato centrado en la amistad y el amor, que se asoma con extrema sensibilidad y de manera sincera al universo adolescente. Una historia de lealtades y traiciones, malentendidos, dudas y desengaños, que, no obstante, concluye con un final esperanzador. Aunque a veces las relaciones entre el grupo resultan complicadas, siempre aportan algo fundamental para la formación de los jóvenes en su camino hacia la edad adulta.', 'Perdona por no quererte', 1383);
INSERT INTO public.libro VALUES (2071, 2013, 'Fiction', 'OoRKCAAAQBAJ', '9788415791041', 249, 'http://books.google.com/books/content?id=OoRKCAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Cuando la presa se convierte en cazadorTodo comenzó un día cualquiera para aquellas tres adolescentes de Belham, Massachusetts. Ellas iban a pasar un día como cualquier otro, en el bosque bebiendo cerveza y fumando. Todo iba bien, hasta que presenciaron aquella escena. Ellas no estaban preparadas para ver algo así, les arrancó la inocencia de cuajo, quebró su amistad, y se convirtió en un reguero de sangre y dolor, mucho dolor... Han pasado veinticinco años desde que ocurriera aquello, y el secuestro de Carol Cranmore, una adolescente de Belham, ha puesto en guardia a la policía y al FBI. Estos últimos, creen saber a lo que se enfrentan, un nuevo ataque de un asesino en serie, posiblemente el mismo que llevan buscando más de veinticinco años... conocido como El Viajero. Solo existe una persona que haya sido capaz de escapar de las garras de este asesino, pero su estado es tan deplorable que apenas puede que ayuda a la investigación que están llevando a cabo. Darby McCormick, miembro del Departamento de Policía de Boston, es acosada por los fantasmas del pasado, y asumirá este caso como algo personal. Intentara encontrar y salvar a Carol, aunque le cueste la vida en el intento... Mientras tanto, Carol despierta en una celda oscura. Está asustada, no sabe donde está...oye gritos a lo lejos...gritos de mujeres encerradas como ella. Pero de vez en cuando suena un zumbido, y todas las celdas se abren. Carol cruza el umbral, bajo la atenta mirada de un sádico asesino, dispuesto a dar rienda suelta a sus fantasías mas perversas. Se inicia una caza que solo tiene dos reglas básicas: esconderse o morir.', 'Desaparecidas', 1384);
INSERT INTO public.libro VALUES (2072, 1993, 'Ficción', '6wsgEfdthv0C', NULL, 584, 'http://books.google.com/books/content?id=6wsgEfdthv0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', NULL, 'Hispano americano', 1318);
