INSERT INTO public.libro VALUES (2120, 2000, 'Saving and investment', 'MMJHNjLtbOQC', '9789709051278', 198, 'http://books.google.com/books/content?id=MMJHNjLtbOQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'El ahorro de los hogares urbanos en México, 1984 y 1994', 1417);
INSERT INTO public.libro VALUES (2121, 1985, 'Ficción', '-bw9CgAAQBAJ', '9788436911824', 354, 'http://books.google.com/books/content?id=-bw9CgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Listado y características de los españoles que fueron becados para realizar investigaciones en 1984.', 'Becarios españoles de investigación. PFPI-1984', 1418);
INSERT INTO public.libro VALUES (2122, 2021, 'Comics & Graphic Novels', 'Am-REAAAQBAJ', '9788466352062', 0, 'http://books.google.com/books/content?id=Am-REAAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 'En el año 1984, Londres es una ciudad lúgubre en la que la Policía del Pensamiento controla de forma asfixiante la vida de los ciudadanos. Winston Smith es un peón de este engranaje perverso y su cometido es reescribir la historia para adaptarla a lo que el Partido considera la versión oficial de los hechos. Hasta que decide replantearse la verdad del sistema que los gobierna y somete. El artista gráfico Fido Nesti reelabora en estas páginas la obra maestra del autor y novela cumbre del subgénero distópico, dotando de rostros, cuerpos y paisajes un mundo que cada día que pasa resulta menos difícil de imaginar. «Aquí ya no estamos solo ante lo que habitualmente reconocemos como "literatura" e identificamos con la buena escritura. Aquí estamos, repito, ante energía visionaria. Y no todas las visiones se refieren al futuro, o al Más Allá.» -Umberto Eco «Un libro magnífico y profundamente interesante.» -Aldous Huxley ENGLISH DESCRIPTION "In 1984, London is a gloomy city in which the Thought Police suffocatingly control the lives of its citizens. Winston Smith is a pawn in this perverse game and his task is to rewrite history to adapt it to what the Party considers the official version of events. Until he decides to rethink the truth of the system that governs and subjugates them. In these pages, the graphic artist Fido Nesti re-elaborates the author''s masterpiece of the dystopian subgenre, endowing with faces, bodies, and landscapes a world that with each passing day becomes less difficult to imagine. ‘Here we are no longer alone with what we usually recognize as "literature" and identify with good writing. Here we are, I repeat, before visionary energy. And not all visions refer to the future, or the Hereafter.’ -Umberto Eco ‘A magnificent and deeply interesting book.’ -Aldous Huxley "', '1984 (novela gráfica) / 1984 (Graphic Novel)', 1234);
