INSERT INTO public.libro VALUES (2080, 2009, 'Education', 'ECBRqk8ZS9wC', '9788400088729', 436, 'http://books.google.com/books/content?id=ECBRqk8ZS9wC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'La autora centra sus investigaciones desde 1998, en el estudio y recuperación del patrimonio histórico educativo del Instituto del Cardenal Cisneros. Sobre todo le interesa el papel que, desde 1837, ha venido desarrollando el profesor de bachillerato en la sociedad de su tiempo, influencia que analiza especialmente a través de la pervivencia del profesor en la memoria de sus alumnos.', 'El Instituto del Cardenal Cisneros de Madrid, 1845-1877', 1393);
