INSERT INTO public.libro VALUES (2103, 2025, 'Reference', '7M1NEQAAQBAJ', NULL, 4993, 'http://books.google.com/books/content?id=7M1NEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'La Dirección General de los Registros y del Notariado fue suprimida por Real Decreto 139/2020, de 28 de enero, por el que se establece la estructura orgánica básica de los departamentos ministeriales (artículo 2.2), siendo el órgano directivo que asume sus funciones la Dirección General de Seguridad Jurídica y Fe Pública. El Anuario del año 2021, que ahora se publica, presenta una división más racional para facilitar el uso y la consulta de sus contenidos y al mismo tiempo aprovechar las ventajas que nos ofrece la tecnología. La obra recoge las resoluciones dictadas por la Dirección General organizadas con arreglo a dos índices, cronológico y sistemático, para facilitar su consulta. Primera edición: febrero de 2025. https://cpage.mpr.gob.es Editor: Ministerio de la Presidencia, Justicia y Relaciones con la Cortes Secretaría General Técnica) y Agencia Estatal Boletín Oficial del Estado © Ministerio de la Presidencia, Justicia y Relaciones con la Cortes y Agencia Estatal Boletín Oficial del Estado ISSN: 2660-6453 (Edición en línea, PDF) NIPO (AEBOE): 144-25-012-1 (Edición en línea, PDF) NIPO (Ministerio de la Presidencia, Justicia y Relaciones con la Cortes): 143-25-009-0 (Edición en línea, PDF) Imprenta Nacional de la Agencia Estatal Boletín Oficial del Estado Avda. de Manoteras, 54. 28050 MADRID 4.993 páginas Edición no venal.', 'Anuario de la Dirección General de Seguridad Jurídica y Fe Pública (2021)', 1408);
INSERT INTO public.libro VALUES (2104, NULL, 'Business & Economics', '2ZjIDwAAQBAJ', '9786075411378', 727, 'http://books.google.com/books/content?id=2ZjIDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'FISCO AGENDA La mejor recopilación de leyes fiscales en versión económica, con casos prácticos y justo con las leyes que tú necesitas. Es tu compañera ideal. 1a. SECCION Abreviaturas. Indice Temático. Ley del Impuesto Sobre la Renta Correlacionada. Reglamento de la Ley del Impuesto Sobre la Renta. 2a. SECCION Ley del Impuesto al Valor Agregado Correlacionada. Reglamento de la Ley del Impuesto al Valor Agregado. Ley del Impuesto Especial Sobre Producción y Servicios Correlacionada. Reglamento de la Ley del Impuesto Especial Sobre Producción y Servicios. 3a. SECCION Código Fiscal de la Federación Correlacionado. Reglamento del Código Fiscal de la Federación. 4a. SECCION Ley para Determinar el Valor de la Unidad de Medida y Actualización. Ley Federal de Procedimiento Contencioso Administrativo. Ley de Ingresos de la Federación. Ley Federal de los Derechos del Contribuyente. Ley del Servicio de Administración Tributaria. Ley de Ayuda Alimentaria para los Trabajadores. Reglamento de la Ley de Ayuda Alimentaria para los Trabajadores. Principales Disposiciones Relacionadas con CFF, ISR y Otras Disposiciones Costo Porcentual Promedio de Captación 1992, 1993, 1994, 1995, 1996, 1997, 1998, 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018 y 2019. Tabla del Indice Nacional de Precios al Consumidor. Tipo de Cambio para Solventar Obligaciones Denominadas en Moneda Extranjera Pagaderas en la República Mexicana 2019. Salarios Mínimos 2020. Resolución del H. Consejo de Representantes de la Quinta Comisión Nacional para la Participación de los Trabajadores en las Utilidades de las Empresas. Decreto que Compila Diversos Beneficios Fiscales y Establece Medidas de Simplificación Administrativa. Decreto por el que se Otorgan Estímulos para Promover la Incorporación a la Seguridad Social. Decreto por el que se Otorgan Beneficios Fiscales a quienes Tributen en el Régimen de Incorporación Fiscal. Decreto por el que se Amplían los Beneficios Fiscales a los Contribuyentes del Régimen de Incorporación Fiscal. Decreto por el que se Otorga un Estímulo Fiscal en Materia de Deducción Inmediata de Bienes Nuevos de Activo Fijo para las Micro y Pequeñas Empresas Decreto que Otorga Diversas Facilidades Administrativas en Materia del Impuesto Sobre la Renta Relativos a Depósitos o Inversiones que se Reciban en México 5a. SECCION Casos Prácticos.', 'FISCO AGENDA 2020', 1409);
