INSERT INTO public.libro VALUES (2108, NULL, 'Business & Economics', 'vVrMDwAAQBAJ', '9786075411774', 1014, 'http://books.google.com/books/content?id=vVrMDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Con las principales leyes en materia Fiscal, con casos prácticos, correlacionada, tematizada y con la mejor presentación. Para el ejecutivo Fiscal. Contenido General Abreviaturas. Indice Temático. Ley del Impuesto Sobre la Renta Correlacionada. Decreto de Estímulos Fiscales Región Fronteriza Norte. Reglamento de la Ley del Impuesto Sobre la Renta. Ley del Impuesto al Valor Agregado Correlacionada y Reglamento. Ley del Impuesto Especial Sobre Producción y Servicios Correlacionada y Reglamento. Código Fiscal de la Federación Correlacionado y Reglamento. Ley de Ingresos de la Federación. CONTENIDO COMPLEMENTO AGENDA FISCAL CASOS PRACTICOS. Ley para Determinar el Valor de la Unidad de Medida y Actualización. Ley Federal de Procedimiento Contencioso Administrativo. Ley Federal de los Derechos del Contribuyente. Ley Orgánica de la Procuraduría de la Defensa del Contribuyente. Ley del Servicio de Administración Tributaria. Reglamento Interior del Servicio de Administración Tributaria. Estatuto del Servicio Fiscal de Carrera. Acuerdo Mediante el cual se Delegan Diversas Atribuciones a los Servidores Públicos del Servicio de Administración Tributaria. Ley Orgánica del Tribunal Federal de Justicia Administrativa. Reglamento Interior del Tribunal Federal de Justicia Fiscal y Administrativa. Ley de Coordinación Fiscal. Reglamento del Registro Público Unico de Financiamientos y Obligaciones de Entidades Federativas y Municipios. Ley Federal del Impuesto Sobre Automóviles Nuevos. Ley de Ayuda Alimentaria para los Trabajadores. Reglamento de la Ley de Ayuda Alimentaria para los Trabajadores. Ley de Contribución de Mejoras por Obras Públicas Federales de Infraestructura Hidráulica. Tipo de Cambio para Solventar Obligaciones Denominadas en Moneda Extranjera Pagaderas en la República Mexicana 2019. Tabla del Indice Nacional de Precios al Consumidor. Costo Porcentual Promedio de Captación. Salarios Mínimos. Resolución del H. Consejo de Representantes de la Quinta Comisión Nacional para la Participación de los Trabajadores en las Utilidades de las Empresas. Resolución por la que se da Cumplimiento a la Fracción VI del Artículo 126 de la Ley Federal del Trabajo. Decreto que Compila Diversos Beneficios Fiscales y Establece Medidas de Simplificación Administrativa. Decreto por el que se Otorgan Estímulos para Promover la Incorporación a la Seguridad Social. Decreto por el que se Otorgan Beneficios Fiscales a quienes Tributen en el Régimen de Incorporación Fiscal. Decreto por el que se Amplían los Beneficios Fiscales a los Contribuyentes del Régimen de Incorporación Fiscal. Decreto por el que se Otorga un Estímulo Fiscal en Materia de Deducción Inmediata de Bienes Nuevos de Activo Fijo para las Micro y Pequeñas Empresas. Decreto que Otorga Diversas Facilidades Administrativas en Materia del Impuesto Sobre la Renta relativos a Depósitos o Inversiones que se Reciban en México.', 'AGENDA FISCAL Y COMPLEMENTO 2020', 1409);
INSERT INTO public.libro VALUES (2109, 2018, 'Ficción', 'XMhsDwAAQBAJ', '9789264306035', 220, 'http://books.google.com/books/content?id=XMhsDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Esta nueva edición de Panorama de la Salud presenta la más reciente información comparable sobre el estado de salud de las poblaciones y el desempeño de los sistemas de salud de los países de la OCDE. Donde es posible, contiene información de países socios (Brasil, China, Colombia, Costa Rica ...', 'Panorama de la Salud 2017 Indicadores de la OCDE', 1392);
INSERT INTO public.libro VALUES (2110, NULL, 'Business & Economics', 'h0tYDwAAQBAJ', NULL, 432, 'http://books.google.com/books/content?id=h0tYDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'AGENDA ELECTORAL, Con las disposiciones que realmente necesitas en esta Materia. Contenido: Normas Constitucionales en Materia Electoral (Arts. 6o., 34 al 36, 39 al 41, 51 al 60, 85, 99, 108, 116, 122) Código Penal Federal (Disposiciones Relativas en Materia Electoral Título Vigesimocuarto) Ley General de Instituciones y Procedimientos Electorales. Reglamento de Sesiones para las Juntas Locales y Distritales Ejecutivas del Instituto Federal Electoral. Reglamento de Fiscalización. Reglamento de Procedimientos Sancionadores en Materia de Fiscalización. Ley General de Partidos Políticos. Ley Federal de Consulta Popular. Ley General en Materia de Delitos Electorales. Ley General del Sistema de Medios de Impugnación en Materia Electoral. Reglamento de Radio y Televisión en Materia Electoral. Reglamento Interno del Tribunal Electoral del Poder Judicial de la Federación. Reglamento de Quejas y Denuncias del Instituto Nacional Electoral. Reglamento Interior del Instituto Nacional Electoral. Reglamento de Sesiones del Consejo General del Instituto Nacional Electoral. Reglamento del Instituto Nacional Electoral en Materia de Transparencia y Acceso a la Información Pública. Reglamento de Comisiones del Consejo General del Instituto Nacional Electoral. Reglamento de Sesiones de los Consejos Locales y Distritales del Instituto Nacional Electoral. Reglamento de Sesiones de la Junta General Ejecutiva del Instituto Nacional Electoral.', 'AGENDA ELECTORAL 2018', 1409);
INSERT INTO public.libro VALUES (2115, 2021, 'Fiction', 'JGuREAAAQBAJ', '9788439737933', 0, 'http://books.google.com/books/content?id=JGuREAAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', '«Hoy, mamá ha muerto. O tal vez ayer, no sé.» Publicada originalmente en 1942, El extranjero es la primera novela de Albert Camus y una de sus obras más emblemáticas. Ahora con nueva traducción al español de María Teresa Gallego Urrutia y Amaya García Gallego, este libro capital para la cultura del siglo XX transcurre en Argelia y narra la anodina vida de Meursault, un joven oficinista que vive en perpetua apatía. Cuando recibe la noticia del fallecimiento de su madre, la encaja con la mayor impasibilidad. Obligado a abandonar la capital y viajar para asistir al funeral, Meursault desea que la ceremonia sea breve para regresar a su casa. Esa indiferencia existencial marca sus días, avanzando sin reaccionar a la muerte de su madre, al afecto de su amada y ni tan siquiera a un crimen que cometerá con idéntica desidia, incapaz de ver el alcance moral de sus actos. Camus retrata magistralmente la indolencia del hombre del siglo XX, un hombre que no encuentra su lugar, extranjero en su propio mundo. Este personaje escéptico y desapasionado que ha abandonado su condición de sujeto autónomo sigue siendo hoy un imprescindible referente literario y existencial. ENGLISH DESCRIPTION With the intrigue of a psychological thriller, Camus''s masterpiece gives us the story of an ordinary man unwittingly drawn into a senseless murder on an Algerian beach. Behind the intrigue, Camus explores what he termed "the nakedness of man faced with the absurd" and describes the condition of reckless alienation and spiritual exhaustion that characterized so much of twentieth-century life. First published in 1946.', 'El extranjero / The Stranger', 1291);
