INSERT INTO public.libro VALUES (2147, 2008, 'Fiction', 'v3dVYIhXFf8C', '9788498412185', 214, 'http://books.google.com/books/content?id=v3dVYIhXFf8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', '«A través de estos relatos, Rilke va apartando los “fantasmas” que le asaltan en esos años clave de su vida: los de su distante padre [...], los de los seres que le acosan en la realidad de las academias militares, o esos seres anónimos y grises que cruzan las calles de la gran urbe desolada. La sensibilidad del poeta le arrastra de continuo hacia otra realidad […]. Va librándose, pues, el escritor gracias a sus cuentos juveniles de esos “fantasmas” y para ello debe llevar a sus personajes a esas situaciones extremas que imponen la violencia, la prostitución, la venganza […], la muerte. […] En ningún momento la obsesión de Rilke por estos temas sórdidos implica una mirada única y realista. […] Hay en ellos, sí, esa lectura descarnada y muy dura de la realidad, pero sólo en la medida en que es reveladora del sentido de una piedad profunda que hay detrás de los hechos chocantes o violentos y que el ser humano precisa para sobrellevar la vida y salvarse.» Antonio Colinas La condición humana es una de las fuentes que ha llevado a todo tipo de personas a preguntarse por el sentido de la vida. Para Rilke (1875-1926), uno de los mejores poetas en lengua alemana de todos los tiempos, el dolor provoca en nosotros la ternura y el amor por los desvalidos, la más profunda y sincera compasión a través de la cual una endeble pero también sólida esperanza aporta un camino de redención.', 'Liese la pelirroja y otros cuentos', 1431);
INSERT INTO public.libro VALUES (2148, 2000, 'Juvenile Nonfiction', 'sWOc2_VbSxMC', '9788489756366', 302, 'http://books.google.com/books/content?id=sWOc2_VbSxMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Cambridge Spanish offers a wide range of tools for the language classroom, from illustrated elementary readers to advanced Spanish film and literature textbooks. These materials supplement and enhance Cambridge''s three core Spanish series: the elementary course ¡Hola Mundo!, ¡Hola, Amigos!; the secondary course Mundo Real; and the introductory college course Entornos.', 'Literatura para la vida', 1432);
