INSERT INTO public.libro VALUES (2157, 1937, 'Philosophy', 'ZHxYAAAAMAAJ', NULL, 382, 'http://books.google.com/books/content?id=ZHxYAAAAMAAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'Descartes', 1440);
INSERT INTO public.libro VALUES (2160, 2020, 'Fiction', 'mbjbDwAAQBAJ', '9788490656747', 692, 'http://books.google.com/books/content?id=mbjbDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', '«Tolstói es un gigante entre los demás escritores. Un elefante entre los demás animales.» IVÁN TURGUÉNEV Desde fábulas y apólogos de un solo párrafo hasta largos relatos en el umbral de la novela corta, las sesenta y siete piezas recogidas en este volumen componen una selección amplia y significativa de la narrativa breve de Tolstói. De 1857 a 1909, incluyendo textos ineludibles como «El prisionero del Cáucaso», «Historia de un caballo», «El padre Sergio» o «El diablo» junto a otros prácticamente desconocidos en español como los cuentos del «Nuevo abecedario», «Las memorias de un loco», «Buda» o «Divino y humano», sin olvidar «Cuánta tierra necesita un hombre» (según Joyce, el mejor cuento escrito jamás), esta antología preparada y traducida por Víctor Gallego cubre la trayectoria narrativa de Tolstói en todas sus fases y estilos cruciales.', 'Relatos', 1442);
INSERT INTO public.libro VALUES (2161, 2024, 'Literary Collections', 'RwvfEAAAQBAJ', '9783989887800', 442, 'http://books.google.com/books/content?id=RwvfEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'depreciated', 'depreciated', 1443);
INSERT INTO public.libro VALUES (2162, 2023, 'Fiction', 'oxqyEAAAQBAJ', '9786558941576', 45, 'http://books.google.com/books/content?id=oxqyEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'León Tolstói fue un escritor ruso nacido en 1828. Padre de la novela moderna y autor de obras extraordinarias como: Guerra y Paz, Anna Karénina, La muerte de Iván Ilich, Los cosacos y numerosos ensayos sobre la religión, la política y la educación. . Tolstói fue una figura popular de alcance mundial, algo desconocido para la época, y más en la Rusia zarista de principios del XX. Cuanta Tierra Necesita un Hombre era, para James Joyce, el mejor cuento de Tolstói. El libro, fue escrito en 1886, el mismo año en que apareció La muerte de Iván Ilich y es, además de una lección con plena vigencia, una ventana al ideario lógico, reflexivo y desesperado del espléndido escritor ruso.', 'Cuánta Tierra Necesita un Hombre', 1444);
INSERT INTO public.libro VALUES (2163, 2015, 'Biography & Autobiography', 'eC2SDwAAQBAJ', '9788432145186', 324, 'http://books.google.com/books/content?id=eC2SDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'La lectura de un clásico como Lev Tolstoi es la mejor cura para el alma, el mejor sistema de apertura del corazón. Pero también muestra el lado contrario, el abismo que puede abrirse entre los hombres. Los clásicos curan, pero también hieren. Tolstoi puede aportar serenidad y comprensión, pero también capacidad de protesta contra la realidad. Es esa la naturaleza salvaje que habita tras la pluma del más clásico y sereno de todos los escritores rusos. El autor tiene en cuenta lo escrito hasta ahora sobre Tolstoi y, sin abandonar el cauce cronológico, destaca su pensamiento, su intención y la evolución de su alma. Eso le permite contrastar sus ideas con las de la sociedad y los autores de su tiempo.', 'Lev Tolstoi. Su vida y su obra.', 1445);
INSERT INTO public.libro VALUES (2164, 2025, 'Art', 'BiNOEQAAQBAJ', '9788583865339', 484, 'http://books.google.com/books/content?id=BiNOEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'El reino de Dios está en vosotros es una profunda exploración de la no violencia, la conciencia personal y las implicaciones morales de las enseñanzas cristianas. León Tolstói critica la religión institucionalizada y la autoridad del Estado, argumentando que el verdadero cristianismo reside en la transformación espiritual individual más que en los dogmas externos. A través de un examen riguroso de la historia, la filosofía y la teología, el libro desafía a los lectores a reconsiderar su complicidad en los sistemas de opresión y a adoptar una ética radical de amor y resistencia a la violencia. Desde su publicación, El reino de Dios está en vosotros ha sido reconocido como una de las obras filosóficas más influyentes de Tolstói. Su defensa de la resistencia no violenta inspiró a figuras clave como Mahatma Gandhi y Martin Luther King Jr., consolidando su legado como un pilar del pensamiento pacifista. La obra sigue resonando por su análisis de la tensión entre la convicción personal y las exigencias sociales, ofreciendo una crítica contundente a la coerción y la renuncia moral. La relevancia duradera del libro radica en su capacidad para desafiar a los lectores a enfrentar dilemas éticos en sus propias vidas. Al examinar la intersección entre fe, justicia y responsabilidad individual, El reino de Dios está en vosotros invita a reflexionar sobre el poder transformador del coraje moral y el potencial del cambio espiritual y social.', 'El Reino de Dios está en Vosotros', 1446);
INSERT INTO public.libro VALUES (2165, 2019, 'Fiction', 'UMDADwAAQBAJ', '9788577776078', 124, 'http://books.google.com/books/content?id=UMDADwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'La serie de libros "7 mejores cuentos" presenta los grandes nombres de la literatura en lengua española. En este volumen traemos a Léon Tolstói, fue un novelista ruso, considerado uno de los escritores más importantes de la literatura mundial. Sus dos obras más famosas, Guerra y paz y Ana Karénina, están consideradas como la cúspide del realismo ruso, junto a obras de Fiódor Dostoyevski. Sus ideas sobre la "no violencia activa", expresadas en libros como El reino de Dios está en vosotros, tuvieron un profundo impacto en grandes personajes como Gandhi y Martin Luther King. Este libro contiene los siguientes cuentos: - ¿Cuánta tierra necesita un hombre? - Dios ve la verdad pero no la dice cuando quiere - La muerte de Iván Ilich - Las tres preguntas - El origen del mal - Demasiado caro - El perro muerto', '7 mejores cuentos de León Tolstoi', 1446);
INSERT INTO public.libro VALUES (2166, 2023, 'Fiction', 'Qou1EAAAQBAJ', '9786558941538', 437, 'http://books.google.com/books/content?id=Qou1EAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'León Tolstói fue un escritor ruso nacido en 1828. Padre de la novela moderna y autor de obras extraordinarias como: Guerra y Paz, Anna Karénina, La muerte de Iván Ilich, Los cosacos y numerosos ensayos sobre la religión, la política y la educación. . Tolstói fue una figura popular de alcance mundial, algo desconocido para la época, y más en la Rusia zarista de principios del XX. Los Cosacos es una novela escrita por León Tolstói, publicada en el año 1863 y se cree que es un poco autobiográfico, parcialmente basado en las experiencias de Tolstói en el Cáucaso durante las últimas etapas de la Guerra del Cáucaso. Tanto Iván Turguénev como el ganador del Nobel de literatura Iván Bunin, profirieron grandes loas a esta, llegando Turguénev a afirmar que se trataba de su obra favorita de Tolstói.', 'LOS COSACOS Tolstoi', 1444);
INSERT INTO public.libro VALUES (2167, 2020, 'Fiction', 'j03rDwAAQBAJ', NULL, 1473, 'http://books.google.com/books/content?id=j03rDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Para este libro, el crítico literario August Nemo ha elegido las dos novelas más importantes y significativas de León Tolstói que son Ana Karenina y La Felicidad Conyugal. León Tolstoi fue un escritor ruso, profundo pensador social y moral, es considerado uno de los más importantes autores de la narrativa realista de todos los tiempos. Novelas seleccionadas para este libro: Ana Karenina. La Felicidad Conyugal. Este es uno de los muchos libros de la serie Novelistas Imprescindibles. Si te ha gustado este libro, busca los otros títulos de la serie, estamos seguros de que te gustarán algunos de los autores.', 'Novelistas Imprescindibles - León Tolstoi', 1446);
INSERT INTO public.libro VALUES (2168, 2024, 'Literary Collections', 'WzrmEAAAQBAJ', NULL, 2698, 'http://books.google.com/books/content?id=WzrmEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'La "Colección de León Tolstoi" abarca una amplia gama de obras que reflejan la rica complejidad de la condición humana. Entre sus relatos más destacados se encuentran "Guerra y Paz" y "Anna Karénina", donde Tolstoi emplea un estilo narrativo profundo y detallado que mezcla el realismo con reflexiones filosóficas. Su prosa se caracteriza por una exploración meticulosa de sus personajes, enmarcada en el turbulento contexto histórico y social de Rusia del siglo XIX. Tolstoi no solo narra historias; también ofrece una crítica incisiva de la sociedad y el comportamiento humano, lo que otorga a sus obras un trasfondo íntimamente político y ético. León Tolstoi, nacido en 1828 en una familia aristocrática, vivió intensamente los vaivenes de su época. Su experiencia en el ejército y su vida de nobleza lo llevaron a cuestionar las estructuras sociales en las que había sido educado. A lo largo de su vida, Tolstoi buscó mantener una ética personal que desafiaba las convenciones, lo que influenció su escritura. Sus crisis espirituales y su búsqueda de un significado más profundo en la vida son palpables en su narrativa, otorgándole un propósito trascendental a cada una de sus obras. Recomiendo esta colección no solo a aficionados de la literatura clásica, sino también a quienes buscan un examen profundo de la moralidad y la existencia humana. Las obras de Tolstoi no solo entretienen; invitan a la reflexión y el análisis crítico, convirtiendo cada lectura en un viaje hacia la comprensión de nosotros mismos y de los demás. En esta edición enriquecida, hemos creado cuidadosamente un valor añadido para tu experiencia de lectura: - Una Introducción amplia expone las características unificadoras, los temas o las evoluciones estilísticas de estas obras seleccionadas. - La Biografía del Autor destaca hitos personales e influencias literarias que configuran el conjunto de su producción. - La sección de Contexto Histórico sitúa las obras en su época más amplia: corrientes sociales, tendencias culturales y eventos clave que sustentan su creación. - Una breve Sinopsis (Selección) oferece uma visão acessível de los textos incluidos, ajudando al lector a seguir tramas e ideias principais sin desvelar giros cruciais. - Un Análisis unificado examina los motivos recurrentes e los rasgos estilísticos en toda la colección, entrelazando las historias a la vez que resalta la fuerza de cada obra. - Las preguntas de reflexión animan a los lectores a comparar las diferentes voces y perspectivas dentro de la colección, fomentando una comprensión más rica de la conversación general. - Una selección curada de citas memorables muestra las líneas más destacadas de cada texto, ofreciendo una muestra del poder único de cada autor.', 'Colección de León Tolstoi', 1446);
INSERT INTO public.libro VALUES (2169, 2015, 'Fiction', 'KxCvEAAAQBAJ', '9783959280198', 2993, 'http://books.google.com/books/content?id=KxCvEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Ebook con un sumario dinámico y detallado: - Ana Karenina - Guerra y Paz - Resurrección - La muerte de Iván Ilich Lev Nikoláievich Tolstói, también conocido en español como León Tolstói, fue un novelista ruso, considerado uno de los escritores más importantes de la literatura mundial. Sus dos obras más famosas, Guerra y Paz y Ana Karénina, están consideradas como la cúspide del realismo.', 'Obras - Colección de León Tolstoi', 1446);
INSERT INTO public.libro VALUES (2170, 2002, 'Epic literature', 'ssDoS2RIonkC', '9788478446063', 384, 'http://books.google.com/books/content?id=ssDoS2RIonkC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'A través de una rigurosa investigación de los dos grandes escritores de la novela rusa, George Steiner analiza, con gran sabiduría crítica, dos tradiciones literarias seculares: la de la épica, que abarca un largo recorrido vital desde Homero hasta Tolstoi, y la de la visión trágica del mundo, cuya continuidad se desarrolla desde Edipo Rey hasta El rey Lear y Los hermanos Karamazov. Dos visiones opuestas de Dios y del mundo sirven a Steiner para ir esclareciendo toda la evolución de la novela europea y norteamericana, a través de sus figuras más relevantes, porque sólo usando los superlativos, las grandes obras maestras, podemos llegar a entender la esencia de la novela, tan empañada de dogmatismos cerrados y limitadores.', 'Tolstói o Dostoievski', 1447);
INSERT INTO public.libro VALUES (2171, 2024, 'Religion', 'jhsfEQAAQBAJ', '9788441443723', 522, 'http://books.google.com/books/content?id=jhsfEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'El camino de la vida es el testamento espiritual, el legado moral que León Tolstói decidió dejar al mundo en sus últimos días. Es su obra póstuma, pues falleció antes de su publicación, y como tal debe abordarse. Una joya literaria en la que, más preocupado por el mensaje que por las formas, nos ofrece sus reflexiones sobre el ser humano, la religión, la existencia, la espiritualidad, las virtudes o los defectos. A lo largo de estas páginas Tolstói nos ofrece un viaje introspectivo, en el que nos da su perspectiva sobre cuestiones tan trascendentales como la búsqueda de la verdad o la felicidad, el propósito vital o la importancia de una vida recta. Tras una vida plena, pero no siempre fácil, y un acúmulo de sabiduría, Tolstói nos invita en El camino de la vida, a reflexionar sobre el sentido de la existencia y a buscar cauces más profundos y certeros para nuestra vida cotidiana.', 'El camino de la vida', 1446);
INSERT INTO public.libro VALUES (2172, 1900, 'Ficción', 'zQAxAQAAMAAJ', NULL, 158, 'http://books.google.com/books/content?id=zQAxAQAAMAAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'Tolstoi', 1448);
INSERT INTO public.libro VALUES (2173, 2023, 'Fiction', 'IU3mEAAAQBAJ', NULL, 3084, 'http://books.google.com/books/content?id=IU3mEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'La ''Colección integral de León Tolstoi'' se erige como un compendio monumental que abarca las obras más significativas del autor ruso, explorando temas de moralidad, espiritualidad y la condición humana. Con un estilo literario que fluctúa entre lo épico y lo psicológico, Tolstoi utiliza una prosa rica y detallada para combinar narrativas intensas con profundas reflexiones filosóficas, en un contexto literario marcado por el realismo del siglo XIX. Sus novelas, como ''Guerra y paz'' y ''Anna Karénina'', se adentran en la vida de la aristocracia rusa y sus conflictos internos, proporcionando un análisis incisivo sobre las relaciones humanas y la sociedad de su época. León Tolstoi, nacido en 1828 en una noble familia rusa, tuvo una vida llena de experiencias que influyeron en su escritura. Tras una juventud marcada por la frivolidad, un cambio espiritual profundo en su vida, motivado por sus dudas existenciales, lo llevó a cuestionar no solo su lugar en la sociedad, sino también el sentido de la existencia. Este viaje interior se refleja en su obra, donde busca la verdad y la iluminación a través de la literatura, convirtiéndose en uno de los máximos exponentes de la narrativa moral. Recomiendo encarecidamente esta ''Colección integral de León Tolstoi'' a todo lector que desee embarcarse en una travesía literaria que desafía y nutre el intelecto. La profundidad de sus personajes y la complejidad de las tramas son deleites para quienes buscan una lectura que no solo entretenga, sino que también invite a la reflexión sobre la vida y la humanidad. En esta edición enriquecida, hemos creado cuidadosamente un valor añadido para tu experiencia de lectura: - Una Introducción amplia expone las características unificadoras, los temas o las evoluciones estilísticas de estas obras seleccionadas. - La Biografía del Autor destaca hitos personales e influencias literarias que configuran el conjunto de su producción. - La sección de Contexto Histórico sitúa las obras en su época más amplia: corrientes sociales, tendencias culturales y eventos clave que sustentan su creación. - Una breve Sinopsis (Selección) oferece uma visão acessível de los textos incluidos, ajudando al lector a seguir tramas e ideias principais sin desvelar giros cruciais. - Un Análisis unificado examina los motivos recurrentes e los rasgos estilísticos en toda la colección, entrelazando las historias a la vez que resalta la fuerza de cada obra. - Las preguntas de reflexión animan a los lectores a comparar las diferentes voces y perspectivas dentro de la colección, fomentando una comprensión más rica de la conversación general. - Una selección curada de citas memorables muestra las líneas más destacadas de cada texto, ofreciendo una muestra del poder único de cada autor.', 'Colección integral de León Tolstoi', 1446);
INSERT INTO public.libro VALUES (2174, 2023, 'Literary Collections', 'eSbmEAAAQBAJ', NULL, 920, 'http://books.google.com/books/content?id=eSbmEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'La ''Narrativa Breve de León Tolstoi'' es un conjunto de relatos que refleja la maestría del autor en la exploración de la naturaleza humana y su relación con la moralidad y la espiritualidad. En esta obra, Tolstoi emplea un estilo sencillo y magistral que realza la profundidad de sus personajes y tramas, en un contexto literario marcado por el realismo y la crítica social del siglo XIX. Los relatos, cargados de simbolismo y experiencias vitales, revelan conflictos internos y dilemas éticos que han resonado en la humanidad a lo largo del tiempo. Cada cuento es un microcosmos donde se despliegan, con gran sutileza, las tensiones entre el deber y el deseo, lo terrenal y lo divino. León Tolstoi, uno de los gigantes de la literatura rusa, es conocido por su búsqueda constante de la verdad y la justicia, influencias que inevitably permeaban su escritura. Criado en una familia aristocrática, su vida estuvo marcada por profundas crisis existenciales y una búsqueda de significado que lo llevaron a explorar temas filosóficos y religiosos. Estas experiencias informaron su narrativa, ofreciendo al lector una reflexión sobre la condición humana. Recomiendo encarecidamente esta colección a todos los amantes de la literatura que busquen no solo un deleite estético, sino también una profunda reflexión sobre la vida y la moralidad. La ''Narrativa Breve'' no solo enriquece nuestra comprensión de Tolstoi, sino que también invita a cuestionar nuestras propias convicciones y valores.', 'Narrativa Breve de León Tolstoi', 1446);
INSERT INTO public.libro VALUES (2175, 1899, 'Ficción', 'W1dgAAAAMAAJ', NULL, 674, 'http://books.google.com/books/content?id=W1dgAAAAMAAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'The Complete Works of Lyof N. Tolstoi', 1449);
INSERT INTO public.libro VALUES (2176, 2015, 'Fiction', 'uqNjDwAAQBAJ', '9788026835752', 910, 'http://books.google.com/books/content?id=uqNjDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Este ebook presenta "Cuentos de León Tolstoi" con un sumario dinámico y detallado. Presenta una selección amplia y significativa de la narrativa breve de Tolstói donde se encuentran algunos de los más conocidos relatos como "Historia de un caballo", "El padre Sergio" o "El diablo". Leon Tolstoi es considerado uno de los escritores más importantes de la segunda mitad del siglo XX y uno de los novelistas excepcionales de todos los tiempos. Entre su extensa producción literaria, una de sus novelas breves más sobresalientes es precisamente: La muerte de Iván Ilich, en la que, sin duda alcanza la perfección. Su magnifica narrativa, donde la acción fluye como un torrente, permite asistir a las zonas oscuras de la decadencia del ser humano. Decadencia que ocurre primero en lo corporal y después en lo espiritual, su lenguaje preciso y certero nos muestra como el dolor recorre y abarca lenta, contundentemente, el cuerpo de su protagonista, hasta su placentera muerte. Liev Nikoláievich Tolstói ( 1828 - 1910) fue un novelista ruso ampliamente considerado como uno de los más grandes escritores de occidente y de la literatura mundial. Sus más famosas obras son Guerra y Paz y Anna Karénina, y son tenidas como la cúspide del realismo. Sus ideas sobre la no violencia activa , expresadas en libros como El reino de Dios está en vosotros tuvieron un profundo impacto en grandes personajes como Gandhi y Martin Luther King.', 'Cuentos de León Tolstoi', 1446);
