INSERT INTO public.libro VALUES (2185, 1881, 'Boston (Mass.)', 'KZo_AQAAMAAJ', NULL, 428, 'http://books.google.com/books/content?id=KZo_AQAAMAAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Quarterly accession lists; beginning with Apr. 1893, the bulletin is limited to "subject lists, special bibliographies, and reprints or facsimiles of original documents, prints and manuscripts in the Library," the accessions being recorded in a separate classified list, Jan.-Apr. 1893, a weekly bulletin Apr. 1893-Apr. 1894, as well as a classified list of later accessions in the last number published of the bulletin itself (Jan. 1896)', 'Bulletin', 1456);
