INSERT INTO public.libro VALUES (2196, 2023, 'Fiction', 'FGaoEAAAQBAJ', '9788490659557', 172, 'http://books.google.com/books/content?id=FGaoEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', '«En una novela tiene que haber un héroe, y aquí se han reunido deliberadamente todos los rasgos del antihéroe», dice el narrador sin nombre de Memorias del subsuelo, que Fiódor M. Dostoievski publicó en 1864 en la nueva revista Época de su hermano Mijaíl, a quien había confesado su inquietud por el «tono áspero y salvaje» del texto. En su primera parte, un funcionario de grado medio de cuarenta años, ya retirado, se dirige a un imaginario público como un orador: entre burlas, paradojas y violentas interpelaciones, confiesa su orgulloso aislamiento de la sociedad, sus constantes atentados contra «todo lo hermoso y lo sublime» y su firme convicción de que la civilización no podrá salvar al ser humano, condenado por el libre albedrío a desafiar a la razón y saborear el mal. En la segunda parte, a partir del recuerdo de una anécdota de juventud, la novela empieza a poblarse de personajes —tenientes engreídos, amigos aduladores, criados altivos, jóvenes prostitutas— que acaban de perfilar, con sus juergas y sus desaires, el característico universo dostoievskiano. El «subsuelo» desde donde escribe el protagonista es un espacio simbólico de «la falta de contacto con la vida» y del «presuntuoso rencor» que esta genera, pero también un refugio donde reina una falsa sensación de «tranquilidad». Es el lugar donde viven los insectos, las arañas y los ratones, y también el hombre superfluo, «incapaz de amar», ese gran prototipo de la literatura rusa.', 'Memorias del subsuelo', 1258);
INSERT INTO public.libro VALUES (2197, 2026, 'Fiction', 'xOi8EQAAQBAJ', '9791387833572', 183, 'http://books.google.com/books/content?id=xOi8EQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', '«Soy un hombre enfermo... Soy un hombre lleno de rabia. Un hombre desagradable, también». Así se presenta el narrador anónimo de Memorias del subsuelo, una de las voces más perturbadoras y fascinantes de la literatura moderna. Desde su escondrijo en San Petersburgo, este hombre lúcido hasta la enfermedad y orgulloso hasta la autodestrucción desgrana una confesión que es a la vez diatriba, autopsia moral y descenso a las zonas más incómodas de la conciencia. Entre invectivas, paradojas y destellos de ternura, retrata su batalla íntima contra el mundo —y contra sí mismo— con una sinceridad que duele. Considerada la primera gran novela existencialista, esta obra breve e incandescente inaugura muchas de las preguntas que definirían el siglo XX: la libertad, el deseo de autodestrucción, el placer del sufrimiento y la imposibilidad de ser uno mismo. Dostoievski, maestro insuperable del alma humana, despliega aquí todo su genio en una nueva traducción de Jorge Ferrer que ilumina con precisión quirúrgica la voz del hombre del subsuelo. «Considero que este libro es (y no soy el único) la llave maestra de su obra entera». A. GIDE «Las Memorias del subsuelo... ningún otro texto de novelista alguno ha ejercido tanta influencia sobre el pensamiento y la técnica novelesca del siglo XX». G. STEINER', 'Memorias del subsuelo', 1463);
INSERT INTO public.libro VALUES (2198, 2021, 'Fiction', 'zNNUEAAAQBAJ', '9788418451454', 107, 'http://books.google.com/books/content?id=zNNUEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', '«Una historia desagradable» fue escrita y publicada en 1862 tras una breve gira por España. La historia se publicó en la revista Vremia (Tiempo) de Dostoievski. En un contexto histórico posterior a la reforma emancipadora de 1861 en Rusia, y tras beber de más con dos colegas funcionarios, el protagonista, Ivan Ilich Pralinski, expone su deseo de adoptar una filosofía basada en la bondad y el humanismo hacia personas de menor estatus social. Al marcharse de la reunión inicial, Ivan se da cuenta de que su cochero se ha ido a otro lugar por pensar que la reunión demoraría más tiempo, por lo que decide caminar y pasa de casualidad por una casa donde se celebra la fiesta de casamiento de uno de sus subordinados. Resuelve entonces poner su filosofía en práctica y entra en la fiesta.', 'Una historia desagradable', 1463);
INSERT INTO public.libro VALUES (2199, 2009, 'Short stories, Russian', 'CF3gPQAACAAJ', '9788483468524', 0, 'http://books.google.com/books/content?id=CF3gPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', NULL, 'Cuentos', 1463);
INSERT INTO public.libro VALUES (2202, 2013, 'Fiction', 'cpO7ngEACAAJ', '9781490918884', 220, 'http://books.google.com/books/content?id=cpO7ngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 'El doble es la segunda novela escrita por Fiódor Dostoievski. Describe la vida de un funcionario del Estado ruso, Yakov Petrovich Goliadkin, quien, al ser rechazado en una comida que ofrecía su jefe por el cumpleaños de su hija, su personalidad se «parte» y enfrenta una despiadada lucha interna. La obra contiene aspectos existencialistas y se aborda el tema de la libertad en un tono irónico y malvado. El Doble no es más que la libertad manifestada en el deseo, el desenfreno o el engaño.', 'El Doble', 1465);
INSERT INTO public.libro VALUES (2203, 2024, 'Fiction', 'VmM4EQAAQBAJ', '9791387590154', 47, 'http://books.google.com/books/content?id=VmM4EQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Fiódor Dostoievski trasladó a sus obras las trágicas experiencias que marcaron su vida, reflejando en ellas además hondas preocupaciones respecto a la condición humana y las injusticias sociales, aspectos que lo convirtieron en el mejor exponente del realismo psicológico. Noches blancas, publicada en 1848, es pese a su brevedad un virtuoso ejercicio de introspección psicológica y una peculiar muestra de los vínculos de su autor con el romanticismo. Su joven y solitario protagonista deambula por San Petersburgo azorado por la huida estival de sus habitantes, hallando de manera fortuita a la atormentada Nástenka. Noche tras noche, ambos se reunirán en el muelle y compartirán sus infortunios, a la espera de una cuarta velada que determinará su porvenir. Con su característica construcción literaria dialógica, Dostoievski hace orbitar esta novela en torno a la figura del héroe que triunfa en la derrota, pues es su salvación mirar de frente al desencanto.', 'Noches blancas', 1463);
INSERT INTO public.libro VALUES (2206, 2022, 'Biography & Autobiography', 'mbWHEAAAQBAJ', '9788432162336', 1102, 'http://books.google.com/books/content?id=mbWHEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'La biografía de Dostoievski en cinco volúmenes de Joseph Frank es ampliamente reconocida como la más definitiva, y una de las mejores biografías literarias del último medio siglo. Ahora, el monumental trabajo de 2500 páginas de Frank ha sido hábilmente resumido y condensado en este único volumen de fácil lectura con un nuevo prefacio del autor. Preservando cuidadosamente el aclamado estilo narrativo de la obra original y la combinación de biografía, historia intelectual y crítica literaria, Dostoievski: un escritor en su tiempo ilumina las obras del escritor desde su primera novela, Pobres gentes, hasta Crimen y castigo y Los hermanos Karamazov, situándolos en su contexto personal, histórico y sobre todo ideológico. Más que una biografía en el sentido habitual, se trata de una historia cultural de la Rusia del siglo XIX, que ofrece una rica imagen del mundo en el que vivió Dostoievski y una importante reinterpretación de su vida y obra.', 'Dostoievski', 1467);
INSERT INTO public.libro VALUES (2213, 2011, 'Literary Collections', '72jXCgAAQBAJ', NULL, 53, 'http://books.google.com/books/content?id=72jXCgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Estamos especializados en publicar textos en español. Para encontrar mas títulos busque “NoBooks Editorial” o visite nuestra web http://www.nobooksed.com Contamos con mas volúmenes en español que cualquier otra editorial en formato electrónico y continuamos creciendo. Como en muchas de las obras del autor, la obra está narrada en primera persona por un narrador, sin nombre. El protagonista es el arquetipo del joven soñador y solitario e imagina constantemente su vejez solitaria. Durante uno de sus largos y cotidianos paseos por las calles de San Petersburgo se encuentra con una joven, Nástienka. Hasta entonces, éste nunca había hablado con mujeres y mucho menos se había enamorado, pero hay algo de ella que le hechiza. El relato está estructurado durante cuatro noches y una mañana.', 'Noches Blancas', 1468);
INSERT INTO public.libro VALUES (2214, 1996, 'Language Arts & Disciplines', 'wIz7XSq5eh4C', '9788476584736', 224, 'http://books.google.com/books/content?id=wIz7XSq5eh4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Over de werken van de Russische theoreticus M. Bajtin (1895-1975).', 'Bajtin y sus apócrifos', 1469);
INSERT INTO public.libro VALUES (2217, 2025, 'Fiction', 'rHNJEQAAQBAJ', '9788583865551', 214, 'http://books.google.com/books/content?id=rHNJEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'El jugador es una fascinante exploración de la obsesión, el riesgo y el atractivo destructivo del azar. Fiódor Dostoievski profundiza en la psicología de la adicción y las compulsiones que llevan a los individuos al límite, ambientando la historia en una ciudad turística europea. A través de las experiencias de Alexei Ivánovich, un tutor atrapado entre el juego y un amor no correspondido, la novela examina temas como el poder, el destino y la ilusión del control, retratando un mundo donde la fortuna puede cambiar en un instante. Desde su publicación, El jugador ha sido reconocido por su profunda exploración psicológica y su aguda representación de la debilidad humana. Dostoievski, quien personalmente sufrió una adicción al juego, impregna la narrativa con una visión de primera mano, convirtiéndola en un estudio cautivador sobre la autodestrucción y la emoción del riesgo. Su análisis de la delgada línea entre la ambición y la imprudencia, así como su crítica a la jerarquía social y la desesperación económica, han asegurado su lugar como una obra fundamental de la literatura rusa. La relevancia perdurable de la novela radica en su capacidad para diseccionar la mente humana bajo presión, revelando la naturaleza seductora pero devastadora del juego. Al ilustrar la interacción entre el deseo personal y las fuerzas externas.', 'El Jugador - Dostoyevski', 1471);
INSERT INTO public.libro VALUES (2236, 2007, 'Art', 'wZ3Fjx8OulMC', '9789587160130', 244, 'http://books.google.com/books/content?id=wZ3Fjx8OulMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'The work of Trilnick (b. Colombia 1957) marks the history of video art during the first three decades of its use. The experiences of Trilnick with photography, video, installations, cinema, television, and digital images established him as an innovator and experimental artist that he has maintained throughout his career. This work is a compilation of significant texts old and new. The newer studies help complete the profile of Trilnick and analyze a series of photographs, installations and videos as part of the larger trajectory of his work.', 'Carlos Trilnick', 1482);
INSERT INTO public.libro VALUES (2200, 2016, 'Literary Criticism', 'X28QEQAAQBAJ', '9788432318054', 65, 'http://books.google.com/books/content?id=X28QEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Tras sobrevivir a un pelotón de fusilamiento a los 28 años, Dostoievski nunca se tomó las cosas a la ligera. Sus grandes novelas irrumpen en la escena literaria europea como una sucesión de tormentas y su entendimiento de los recovecos más oscuros y extremos de la mente humana arrojan mucha luz sobre la psicología y la pasión. Sus libros, clásicos de la literatura, inspiraron a escritores y pensadores tan dispares como Nietzsche y Kafka. En "Dostoievski en 90 minutos", Paul Strathern nos ofrece el relato conciso de un experto sobre la vida e ideas de Dostoievski y explica su influencia sobre la literatura y la lucha de los hombres por entender su lugar en el mundo. El libro también incluye una selección de textos de las obras de Dostoievski, una cronología de la vida y época del autor y una selección de lecturas recomendadas para quienes deseen seguir leyendo.', 'Dostoievski en 90 minutos', 1464);
INSERT INTO public.libro VALUES (2201, 2012, 'Fiction', 'WTAJRL9vRXoC', '9788484287742', 734, 'http://books.google.com/books/content?id=WTAJRL9vRXoC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', '«Esta obra singular, concebida por el autor como interludio entre novelas o trabajo preparatorio para El adolescente y Los hermanos Karamázov, es imprescindible para conocer y comprender al escritor y a la persona.» Jesús García Gabaldón, El País Con su reputación literaria plenamente afianzada gracias a Crimen y castigo y Los demonios, Fiódor M. Dostoievski volcó en el periodismo, entre 1873 y 1881, su prodigiosa capacidad de análisis psicológico y su extraordinario talento para la controversia. A raíz de aceptar la dirección de la revista El Ciudadano, comenzó a redactar el que habría de ser su libro más personal, extraño y desconocido. En Diario de un escritor el gran novelista ruso privilegia su compromiso moral con los sucesos más acuciantes de su tiempo, a través de una entreverada mezcla de géneros –autobiografía, ficción, ensayo, crónicas judiciales, necrológicas, estampas de costumbres, breves tratados sobre el carácter nacional-, de la que resulta un experimento de arte integral, un triunfo de la pasión por la libertad humana. En esta selección del inmenso cajón de sastre que es el Diario, impecablemente confeccionada y traducida por Víctor Gallego, se ha prescindido de consideraciones y polémicas hoy trasnochadas. Dos temas obsesivos, profundamente dostoievskianos, recorren sus páginas: los malos tratos a los niños en la familia y las causas de los suicidios. Junto a la ardorosa defensa de la piedad y la justicia, se encuentran también aquí los mejores relatos del autor: «La mansa», «El sueño de un hombre ridículo», «El mujik Marei» y, en especial, «Bobok», que constituye, según Bajtin, «casi un microcosmos de toda su obra».', 'Diario de un escritor', 1258);
INSERT INTO public.libro VALUES (2204, 2004, 'Delitos', 'h3BywgEACAAJ', '9788484036463', 0, 'http://books.google.com/books/content?id=h3BywgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 'Las obras clásicas de literatura en cada volumen son una representación de los mejores y más famosos escritos de los autores. Una introducción maravillosa a la literatura universal, esta serie hermosamente diseñada pone las obras de los autores mundialmente conocidos al alcance de todos. Este volumen incluye dos de las obras más representativas de este autor: Crimen y castigo, estructurada sobre un tema ético, donde un joven mata a una pobre anciana por considerarla un paria de la sociedad y después, gracias al amor, se arrepiente, y, Los hermanos Karamazov. Esta novela gira en torno a las emociones y decisiones de tres hermanos y está ambientada en la cruda realidad de una Rusia previa a la Revolución Bolchevique.', 'Fiodor Dostoievski', 1466);
INSERT INTO public.libro VALUES (2205, 2017, 'Fiction', 'C48fDgAAQBAJ', '9788490652978', 361, 'http://books.google.com/books/content?id=C48fDgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'En abril de 1849 Fiódor Dostoievski, con otros veintisiete jóvenes, era detenido y acusado de «crímenes contra la seguridad del Estado»; unos meses después, se le sometía a un simulacro de ejecución, y finalmente a una condena de ocho años de trabajos forzados en Siberia. En 1862 aparecería en forma de libro Memorias de la casa muerta, el recuento autobiográfico de sus experiencias en presidio, presentado, bajo una ficticia primera persona, la del «difunto» Alexánder Petróvich Goriánchikov. Este hombre, noble e instruido, que jamás ha trabajado, se encuentra de pronto privado de libertad, obligado a los esfuerzos más penosos, rapado y encadenado, en compañía de montañeses, bandoleros, asesinos, presos políticos y mendigos. «Incluso los condenados a pena perpetua soñaban con algo casi imposible.» Fiódor M. Dostoievski', 'Memorias de la casa muerta', 1258);
INSERT INTO public.libro VALUES (2207, 2011, 'Literary Collections', '72jXCgAAQBAJ', NULL, 53, 'http://books.google.com/books/content?id=72jXCgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Estamos especializados en publicar textos en español. Para encontrar mas títulos busque “NoBooks Editorial” o visite nuestra web http://www.nobooksed.com Contamos con mas volúmenes en español que cualquier otra editorial en formato electrónico y continuamos creciendo. Como en muchas de las obras del autor, la obra está narrada en primera persona por un narrador, sin nombre. El protagonista es el arquetipo del joven soñador y solitario e imagina constantemente su vejez solitaria. Durante uno de sus largos y cotidianos paseos por las calles de San Petersburgo se encuentra con una joven, Nástienka. Hasta entonces, éste nunca había hablado con mujeres y mucho menos se había enamorado, pero hay algo de ella que le hechiza. El relato está estructurado durante cuatro noches y una mañana.', 'Noches Blancas', 1468);
INSERT INTO public.libro VALUES (2208, 2023, 'Fiction', 'qmmwEAAAQBAJ', '9786558941590', 53, 'http://books.google.com/books/content?id=qmmwEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Fiodor Mikhailovich Dostoievski nació en Moscú en 1821 y murió en San Petersburgo en 1881. Es reconocido como uno de los más grandes escritores de la literatura soviética e internacional y autor de las obras maestras Crimen y castigo y Los hermanos Karamazov. La obra de Dostoievski, poco comprendida por sus contemporáneos, marcó profundamente el pensamiento moderno y la literatura occidental. El sueño de un Hombre Ridículo es un relato corto escrito en 1877 por Dostoievski, El cuento está estructurado en cinco partes y contado en primera persona por un narrador protagonista que relata la historia de la revelación que tuvo gracias un sueño utópico. La obra explora la soledad del hombre y su posición frente al incierto sentido de la existencia a partir de una visión espiritual, haciendo uso de un humor sutil y del profundo análisis psicológico de los personajes que es usual en las otras obras del autor.', 'El Sueño de un Hombre Ridiculo - Dostoievski', 1463);
INSERT INTO public.libro VALUES (2216, 2015, 'Literary Collections', '31QpDwAAQBAJ', NULL, 244, 'http://books.google.com/books/content?id=31QpDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Estamos especializados en publicar textos en español. Para encontrar mas títulos busque “NoBooks Editorial” o visite nuestra web http://www.nobooksed.com Contamos con mas volúmenes en español que cualquier otra editorial en formato electrónico y continuamos creciendo.', 'Pobres gentes', 1468);
INSERT INTO public.libro VALUES (2237, 1831, 'Ficción', 'ClFHjQeLCJgC', NULL, 260, 'http://books.google.com/books/content?id=ClFHjQeLCJgC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'Historia de Carlos Eduardo, último Príncipe de la casa de Estuardo', 1483);
INSERT INTO public.libro VALUES (2209, 2024, 'Fiction', 'X2L2EAAAQBAJ', '9788411780544', 236, 'http://books.google.com/books/content?id=X2L2EAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Velchanínov, cerca ya de los cuarenta, es «un hombre que había vivido mucho, y a lo grande»: rubio, apuesto, culto y galante, ha dilapidado ya dos herencias y se encuentra en San Petersburgo para resolver un litigio a propósito de una tercera. Es también hipocondríaco y sueña que «una muchedumbre enorme» se junta en su piso para acusarle de un crimen. De pronto reaparece en su vida un antiguo amigo al que hacía nueve años que no veía y con cuya mujer, ahora difunta, tuvo una larga aventura: Trusotski, un funcionario triste y calvo, alcoholizado, que se presenta como «un hombre hundido, pero no hundido sin más, sino radicalmente hundido». El hecho de que Trusotski tenga una hija de unos ocho años, visiblemente maltratada, despierta en Velchanínov el deseo de salvarla y de expiar así «toda mi existencia anterior, hedionda y baldía». Pero la relación entre los dos hombres se debate entre el rencor y la generosidad: sus diálogos, a veces violentos, a veces cómicos, siempre tensos, están llenos de excusas y medias verdades, cuando no de escupitajos y gestos peligrosos. "El eterno marido" (1870), escrita entre "El idiota" y "Los demonios", en la época de su madurez creativa, gira en torno a un lema característico de Dostoievski: «El monstruo más monstruoso es el monstruo con buenos sentimientos». A partir de aquí, no puede esperarse más que una novela en la que todo es «ansioso y febril», pero en la que también hay lugar para la distancia y la parodia.', 'El eterno marido', 1258);
INSERT INTO public.libro VALUES (2210, 2016, 'Literary Collections', 't5qxDQAAQBAJ', NULL, 111, 'http://books.google.com/books/content?id=t5qxDQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'Diario de un escritor y otros escritos', 1468);
INSERT INTO public.libro VALUES (2211, 2023, 'Fiction', 'dz7mEAAAQBAJ', NULL, 1022, 'http://books.google.com/books/content?id=dz7mEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Los hermanos Karamazov es una de las cumbres del pensamiento filosófico y literario de Fiódor Dostoievski, publicada en 1880. Esta obra maestra relata la compleja dinámica familiar de los Karamazov, centrada en la vida de tres hermanos: Dmitri, Iván y Aliosha, cada uno representando distintas facetas de la condición humana y sus contradicciones. Dostoievski emplea un estilo introspectivo y denso que fusiona la narrativa con diálogos profundos, explorando temas como la fe, la moral, el libre albedrío y las relaciones interpersonales en el contexto de la Rusia del siglo XIX, marcada por la agitación social y espiritual. Fiódor Dostoievski, uno de los grandes exponentes de la literatura rusa, vivió un intenso proceso de tormento personal y espiritual que influenció su obra. Su experiencia en la prisión, su cercanía con la filosofía existencialista y su lucha con las cuestiones religiosas y éticas nutrieron su escritura, convirtiéndolo en un autor comprometido con la exploración del alma humana. A través de Los hermanos Karamazov, Dostoievski busca confrontar las heridas de su tiempo, ofreciendo un retrato profundo de la vida y la naturaleza humana. Recomiendo encarecidamente Los hermanos Karamazov a quienes busquen una lectura que trascienda la mera ficción, adentrándose en un estudio filosófico y moral que invita a la reflexión. Esta obra no solo es un deleite literario, sino también un examen profundo de las emociones y dilemas que definen nuestra existencia, lo que la convierte en un clásico atemporal de la literatura universal.', 'Los hermanos Karamazov', 1463);
INSERT INTO public.libro VALUES (2212, 2020, 'Fiction', 'e2PtDwAAQBAJ', '9789874109835', 114, 'http://books.google.com/books/content?id=e2PtDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Los dos relatos que conforman esta obra no escapan a la aguda visión de Dostoievski sobre la condición humana, los sentimientos y las emociones. Sumergirnos en lo profundo del alma de los protagonistas será, sin duda, algo inevitable. Un corazón débil es la historia de una amistad fuerte y compleja, pero también es la tragedia de Vasia Shumkov, un joven con temperamento débil a quien la felicidad parece perturbar. Querido y respetado por todos los que lo rodean, Vasia desarrolla sentimientos de culpa por temer no cumplir con las expectativas, permitiéndose hundirse gradualmente en incomprensibles inquietudes y tristezas. El señor Projarchin, inspirada en hechos reales, cuenta la historia de Semión Ivánovich Projarchin, un personaje enigmático que vive una vida extremadamente pobre, comiendo sobras y durmiendo en una pensión de mala muerte. Su casera y los otros inquilinos sienten pena por él, pero finalmente descubrirán que ese huésped escondía un secreto que no revelaría jamás.', 'Un corazón débil / El señor Projarchin', 1463);
INSERT INTO public.libro VALUES (2215, 1996, 'Fiction', 'Smutnb4TeIIC', '9788489666252', 1540, 'http://books.google.com/books/content?id=Smutnb4TeIIC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'Todos los cuentos', 1470);
INSERT INTO public.libro VALUES (2218, 2020, 'Games & Activities', 'J94WEAAAQBAJ', '9781683250647', 278, 'http://books.google.com/books/content?id=J94WEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Para animar una velada, ocupar una tarde lluviosa de domingo o finalizar agradablemente una buena comida familiar, ¿hay algo mejor que jugar a las cartas? En efecto, en esta obra encontrará numerosos juegos para todas las edades, del más conocido al más insólito: juegos tradicionales (rami, bridge, tarot...), de azar (póquer, bacará, banca...), para niños (póquer mentiroso, revés...), solitarios... Todos los juegos se presentan junto con sus correspondientes reglas, así como con consejos tácticos y ejemplos de partidas que permitirán a todo el mundo aprender a jugar. Para grandes y pequeños, he aquí una obra llena de cartas e ideas... ¡que augura disfrutar de formidables partidas!', 'El gran libro de los juegos de cartas', 1472);
INSERT INTO public.libro VALUES (2219, 2017, 'Ficción', 'nLSxtAEACAAJ', '9781548438012', 82, 'http://books.google.com/books/content?id=nLSxtAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 'Fedor Dostoievski, novelista ruso del siglo XIX y uno de los m�ximos exponentes de la literatura realista de este pa�s, es, a su vez, de los mejores escritores a nivel internacional que ha sabido desgranar, enfrentar y presentar en cada personaje y en cada historia la psicolog�a m�s esencial del ser humano. Sus novelas est�n impregnadas de una profundidad ciertamente existencialista y reflexiva, donde abundan temas como la debilidad humana, la justicia, la bondad, la pobreza, la religi�n, el amor... Su gran �xito, obra culmen en la literatura mundial, es Crimen y Castigo. Pero cada una de sus novelas tiene momentos de perfecci�n absoluta. EL JUGADOR (1866) refleja los dos grandes impulsos -el juego y la pasi�n amorosa- que dominaron la vida de Fi�dor Dostoyevski (1821-1881). En medio de una galer�a de personajes desarraigados y trashumantes que deambulan por la ciudad-balneario de Wiesbaden , la pat�tica figura de Aleksei Ivanovich personifica el goce y la angustia del tipo humano que acaba por canalizar toda su capacidad de protesta en la pasi�n por el juego como v�a de acceso, mediante el dolor y el envilecimiento, a una libertad vorazmente deseada', 'El Jugador', 1466);
INSERT INTO public.libro VALUES (2220, 2016, 'Ficción', 'JLyFvgAACAAJ', '9781539801931', 94, 'http://books.google.com/books/content?id=JLyFvgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 'Novela de indudable trasfondo autobiogr�fico, EL JUGADOR (1866) refleja los dos grandesimpulsos -el juego y la pasi�n amorosa- que dominaron la vida de Fi�dor Dostoyevski (1821-1881).En medio de una galer�a de personajes desarraigados y trashumantes que deambulan por la ciudad-balneario de Wiesbaden (el �Roulettenburg� de la ficci�n), la pat�tica figura de Aleksei Ivanovich personifica el goce y la angustia del tipo humano que acaba por canalizar toda su capacidad de protesta en la pasi�n por el juego como v�a de acceso, mediante el dolor y el envilecimiento, a una libertad vorazmente deseada.', 'El Jugador (Spanish Edition)', 1473);
