INSERT INTO public.libro VALUES (2234, 1880, 'Ficción', 'EU8bAAAAYAAJ', NULL, 328, 'http://books.google.com/books/content?id=EU8bAAAAYAAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'Manual del gobernadorcillo', 1481);
INSERT INTO public.libro VALUES (2235, 2022, 'Fiction', 'BON8EAAAQBAJ', '9782322440757', 122, 'http://books.google.com/books/content?id=BON8EAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'El jugador es una pieza básica en el edificio de la obra de Dostoïevski, conteniendo absolutamente todas las características de sus novelas más famosas, esto es, morbosidad, dramatismo, tensión casi intolerable, agresividad y revelación punzante y sutil de estados anímicos vividos y superados por el genial escritor. Dos pasiones principales campean en este libro: la del juego, que envenenó al propio autor, hasta pocos años antes de morir, y la de un amor hecho de humillaciones, equívocos, odios y abnegación quijotesca. Obra de plena madurez por la reciedumbre de la trama y el trazado de sus personajes atormentados y complejos. El jugador absorbe al lector desde sus primeras líneas.', 'El Jugador', 1463);
INSERT INTO public.libro VALUES (2238, 1681, 'Ficción', 'QyRX2RPM6ioC', NULL, 764, 'http://books.google.com/books/content?id=QyRX2RPM6ioC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'Historia de la vida y hechos del emperador Carlos 5. por el fray Prudencio de Sandoval', 1318);
