INSERT INTO public.libro VALUES (2248, 2016, 'History', 'W2igEQAAQBAJ', '9788437635903', 615, 'http://books.google.com/books/content?id=W2igEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Después de una pesquisa minuciosa, que ha consistido en la exploración y consulta de la abundante documentación original ¿en muchos casos inédita¿ conservada en los archivos más señeros, los autores de este libro han realizado un análisis exhaustivo y comparativo con los textos más conocidos del reinado de Felipe II y que hacían referencia al personaje de don Carlos, para concluir en una obra nueva, innovadora y no exenta de belleza literaria, que definitivamente dilucida algunos de los aspectos más oscuros y controvertidos del siglo XVI y que dio origen al nacimiento de la leyenda negra.', 'Don Carlos. Príncipe de las Españas', 1492);
