INSERT INTO public.libro VALUES (2299, 1885, 'Folklore', 'zeg2AQAAMAAJ', NULL, 286, 'http://books.google.com/books/content?id=zeg2AQAAMAAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'Indian Notes and Queries', 1318);
INSERT INTO public.libro VALUES (2270, 2006, 'Antiques & Collectibles', 'qgkTOar2wJYC', '9789705500046', 282, 'http://books.google.com/books/content?id=qgkTOar2wJYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Aunque el cinematógrafo (el arte de las imágenes en movimiento) se presentó a los primeros espectadores al finalizar el siglo XIX, su génesis técnica y su necesidad social abarcan varias décadas anteriores. Se trataba, por supuesto, de una ilusión, pero no de una ilusión convencional, sino de algo que permitía a los espectadores ver el mundo como no lo habían visto nunca antes. Hoy por hoy es imposible dejar de pensar en este artificio espectacular como la más grande expresión artística del siglo XX. Ciertamente, en la historia humana no se había producido antes un medio de comunicación cuya gestación estuviera tan compactada como la del cine. No obstante ello, y habiendo sido tan importante el desarrollo del cine en México, no fue sino hasta el último tercio del siglo XX cuando se produjeron las primeras investigaciones filmográficas que daban cuenta efectiva de su devenir. Por supuesto que aún quedan lagunas, “hoyos negros” del conocimiento que afortunadamente están siendo llenados por obras como ésta, que no son de lectura exclusiva de un público iniciado y enterado, sino también de los legos que deseen abrevar sabrosamente en él y conocer así usos, costumbres, incidencias sociales y políticas, y, en especial, lo que constituye su temática toral: el accionar del kinetófono y el vitascopio –aparatos poco reconocidos en México- así como del cinematógrafo, que, como se demuestra en este volumen, no fue el primer aparato de imágenes en movimiento en llegar a nuestro país. Francisco Gaytán', '1896: El vitascopio y el cinematógrafo en México', 1501);
INSERT INTO public.libro VALUES (2271, 1966, 'Balls (Parties)', 'zCErAQAAMAAJ', NULL, 156, 'http://books.google.com/books/content?id=zCErAQAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', NULL, 'Las danzas de moros y cristianos', 1502);
