INSERT INTO public.libro VALUES (2273, 2004, 'Moros', 'B4ENAAAAYAAJ', NULL, 92, 'http://books.google.com/books/content?id=B4ENAAAAYAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', NULL, 'Origen de la danza de los morenos', 1504);
INSERT INTO public.libro VALUES (2274, 1997, 'History', 'jYl7AAAAMAAJ', NULL, 198, 'http://books.google.com/books/content?id=jYl7AAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', NULL, 'Danzas precolombinas de América del Sur y sus relaciones con otras culturas mitológicas', 1505);
INSERT INTO public.libro VALUES (2275, 2025, 'Fiction', 'PwGMEQAAQBAJ', '9798231625932', 113, 'http://books.google.com/books/content?id=PwGMEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'In the boundless expanse of the cosmos lies the Siddha’s Mirror, an artifact of divine origin, crafted by ancient seers as both oracle and warning. Unlike an ordinary mirror, it reflects not appearances but destinies, shimmering with visions of what is yet to come. When its dark surface awakens in the hands of the sage-poet Valmiki, it reveals a cataclysm of unimaginable scale: a colossal stone plummeting from the heavens, destined to strike the earth within a single day, unleashing floods, fire, and the ruin of empires. Burdened by this dire knowledge, Valmiki knows the fate of the world now depends on wisdom, will, and the unity of those who can bend the cosmos without breaking it. Summoning the greatest minds and spirits of his age, Valmiki calls together thirty-six rishis, each a master of a different domain of knowledge and power. From Vashishtha’s celestial calculations to Vishwamitra’s fiery strength, they form a living mandala, their gathering a testament to humanity’s last stand against annihilation. Yet the true struggle is not only against the falling stone but also within themselves—their egos, doubts, and temptations of unchecked power. The novella that unfolds is less a tale of individual heroism than of harmony forged through humility, as the sages confront the paradox of salvation: that saving the world must not corrupt it. Through their trials, the Siddha’s Mirror comes to reflect not inevitable destruction, but the redemptive possibility of unity, reminding us that the greatest miracles emerge when light is woven through many hands.', 'The Sidda’s Mirror', 1506);
