INSERT INTO public.libro VALUES (2281, 2002, 'Education', 'XXVwp9trWRsC', NULL, 378, 'http://books.google.com/books/content?id=XXVwp9trWRsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', NULL, 'Education at Iowa', 1318);
INSERT INTO public.libro VALUES (2282, 2007, 'Literary Criticism', 'VNFlAAAAMAAJ', NULL, 344, 'http://books.google.com/books/content?id=VNFlAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 'In Adventures of the Spirit, Phyllis Sternberg Perrakis brings together eleven American and Canadian "literary gerontologists" to examine a new kind of adventure for the older woman in literature. This volume of critical essays analyzes recent works by contemporary women writers whose characters'' midlife and later life changes are mapped in their narratives.Rather than focusing on the painful losses undergone by women of a certain age, recent narratives explore a new kind of adventure of aging, one that is spiritual in nature, enabling new ways of being and becoming, but open-ended and capable of great variation in practice. In particular, these journeys of the spirit focus on the retrospective movement undergone by a midlife or older woman as she is led by inner or outer forces to assess where she has come from and decipher a shape or pattern to her journey.These journeys do not leave the body behind as they map new spiritual territory. Rather they honor spirit''s embrace of the natural world and relationships as well as its aspirations for evolving development and eternal existence. The essays in Adventures of the Spirit employ a wide variety of critical lenses to chart these adventures, including archetypal, Sufi, post-colonial, and feminist analysis; archival research; aboriginal life writing; and trauma theory. These studies bring a new understanding to women''s adventure of age in both literary texts and in life.', 'Adventures of the Spirit', 1511);
INSERT INTO public.libro VALUES (2296, 1997, 'Caste', '-aw3hRAX_DgC', '9788185297682', 1022, 'http://books.google.com/books/content?id=-aw3hRAX_DgC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'A Glossary of the Tribes and Castes of the Punjab and North-West Frontier Province', 1318);
INSERT INTO public.libro VALUES (2298, 1892, 'Ficción', 'Jg3beLL34YkC', NULL, 554, 'http://books.google.com/books/content?id=Jg3beLL34YkC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'Census of India, 1891', 1520);
INSERT INTO public.libro VALUES (2283, 2001, 'Literary Criticism', 'ZrBZAAAAMAAJ', NULL, 256, 'http://books.google.com/books/content?id=ZrBZAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 'The works of Louisiana authors differ from the works of other Southern writers in significant ways. Strong French, Spanish, Native American, and African American traditions shaped Louisiana culture, and Louisiana writers reflect that cultural diversity in their works. So too, historical and religious influences caused Louisiana to develop in a distinct way, and these influences have similarly affected Louisiana writers. The narrative styles employed by these writers generally differ from the styles of other Southern authors. While contemporary Louisiana writers have contributed a substantial body of work to Southern literature, their writings have not received adequate scholarly attention. This book provides a critical introduction to Louisiana literature and gives special attention to how Louisiana literature and culture depart from the rest of the South. The volume is the first collection of scholarly studies focusing on Louisiana writers from the 1930s to the present. Drawing together discussions of 15 of Louisiana''s current premier fiction writers, the collection is organized into three broad sections. The first examines Louisiana narratives and folk traditions; the second, influences of religious traditions on Louisiana writers, including Protestantism, Catholicism, and Paganism; and the third, the construction of gender and race in Louisiana culture. Included are discussions of such writers as Ernest J. Gaines, Anne Rice, James Lee Burke, Moira Crone, John Dufresne, Michael Lee West, Rebecca Wells, and Robert Olin Butler.', 'Songs of the New South', 1512);
