INSERT INTO public.libro VALUES (2287, 1997, 'Education', 'EYmdAAAAMAAJ', NULL, 312, 'http://books.google.com/books/content?id=EYmdAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 'The aim of this book is to help teachers become critically informed about the process of teaching and schooling in the United States. This book is designed to actively engage students in the process of developing a personal perspective for themselves of the function of schooling in our society, and of the special responsibilities teachers have to consider the broader implications of the enterprise of formal education as it occurs in this country.', 'Exploring Themes of Social Justice in Education', 1514);
