INSERT INTO public.libro VALUES (2321, 2019, 'Ficción', 'TQMYywEACAAJ', '9788416693436', NULL, NULL, NULL, 'Choque de Reyes', 1534);
INSERT INTO public.libro VALUES (2322, 2022, 'Comics & Graphic Novels', 'kbJwEAAAQBAJ', '9788411129183', 198, 'http://books.google.com/books/content?id=kbJwEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'El cómic oficial de la saga de fantasía épica que triunfó en TV. Después de los hechos de "Juego de Tronos", la guerra civil asoma en Poniente cuando Daenerys Targaryen, como heredera de la dinastía Targaryen, busca reclamar el Trono de hierro. Arya, con la ayuda de Yoren, un hermano de la Guardia de la Noche, ha huido de Desembarco del Rey pero el camino hasta el Muro está lleno de peligros. Mientras tanto, Sansa acude a un torneo en honor del Rey Joffrey y Bran, en Invernalia, sufre extraños sueños con lobos... La saga de Canción de Hielo y Fuego de George R. R. Martin continúa en el cómic oficial.', 'Juego de Tronos Choque de Reyes no 03/04', 1236);
INSERT INTO public.libro VALUES (2323, 2020, 'Comics & Graphic Novels', 'p7jbDwAAQBAJ', '9788413413082', 192, 'http://books.google.com/books/content?id=p7jbDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'La saga de Canción de Hielo y Fuego de George R. R. Martin continúa en el cómic oficial de la segunda novela. Después de los hechos de "Juego de Tronos", la guerra civil asoma en Poniente cuando Daenerys Targaryen, como heredera de la dinastía Targaryen, busca reclamar el Trono de hierro. Arya, con la ayuda de Yoren, un hermano de la Guardia de la Noche, ha huido de Desembarco del Rey pero el camino hasta el Muro está lleno de peligros. Mientras tanto, Sansa acude a un torneo en honor del Rey Joffrey y Bran, en Invernalia, sufre extraños sueños con lobos... Editorial original: Dynamite.', 'Juego de Tronos Choque de Reyes no 02/04', 1236);
INSERT INTO public.libro VALUES (2324, 2008, 'Education', 'CTLBcQAACAAJ', '9788496208643', 976, NULL, NULL, 'CHOQUE DE REYES BOLSILLO (GEORGE R.R.MARTIN) CANCION DE HIELO Y FUEGO 2 - GIGAMESH BOLSILLO 5', 1318);
INSERT INTO public.libro VALUES (2325, 2011, 'Fiction', '76erpwAACAAJ', '9788496208209', 976, NULL, NULL, 'Choque de reyes (bolsillo)', 1359);
INSERT INTO public.libro VALUES (2326, 2023, 'Fiction', 'Oji9EAAAQBAJ', '9788401031786', 1209, 'http://books.google.com/books/content?id=Oji9EAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Los cinco títulos hasta ahora publicados de «Canción de hielo y fuego», Juego de tronos , Choque de reyes , Tormenta de espadas , Festín de cuervos y Danza de dragones , llegan a las librerías en una nueva edición que conquistará tanto a los fans de esta saga épica como a aquellos que esperan la oportunidad perfecta para adentrarse en sus páginas por primera vez. «Larga vida a George Martin... Sacerdote literario, sabedor de su don para el personaje complejo, el lenguaje vívido y la visión salvaje de los mejores narradores.» The New York Times «Llegará un día en el que te sientas segura y feliz, y de repente tu alegría se te convertirá en cenizas en la boca, y ese día sabrás que la deuda ha quedado saldada.» En el cielo sobre los Siete Reinos, que se hallan asolados por una guerra devastadora, aparece un siniestro cometa color sangre. ¿Acaso se trata de otro augurio terrible sobre las catástrofes que están por llegar? El verano ha terminado, y cuatro líderes se disputan el Trono de Hierro. Mientras tanto, al otro lado del mar, la orgullosa princesa exiliada Daenerys Targaryen está dispuesta a arriesgarlo todo con tal de recuperar la corona que le pertenece por derecho. Puede que, para ella, el cometa de sangre no sea un mal presagio, sino el heraldo de la venganza. Y mientras la batalla continúa, al norte, más allá del Muro, las fuerzas oscuras se vuelven cada vez más poderosas. La crítica ha dicho: «Larga vida a George Martin... Sacerdote literario, sabedor de su don para el personaje complejo, el lenguaje vívido y la visión salvaje de los mejores narradores.» The New York Times «La capacidad de Martin para crear historias apasionantes de intriga es indiscutible.» El Mundo «Entre aquellos que se afanan en la gran tradición épica de la fantasía, Martin es, con diferencia, el mejor.» TIME Magazine «El sobrecogedor alcance de esta epopeya ha hecho que otros escritores de fantasía se lleven las manos a la cabeza.» The Guardian «El escritor de la famosa saga hace tiempo que ha resuelto su porvenir y ha construido su indiscutible trono: el del nuevo rey de la literatura fantástica.» Vanitatis', 'Choque de reyes (Canción de Hielo y Fuego 2)', 1236);
INSERT INTO public.libro VALUES (2327, NULL, 'Ficción', 'IztVzwEACAAJ', '9788413417479', 0, NULL, NULL, 'Juego de Tronos Choque de Reyes no 03/04', 1318);
INSERT INTO public.libro VALUES (2328, 2020, 'Ficción', 'W3pVzwEACAAJ', '9788413410852', 0, NULL, NULL, 'Juego de Tronos : choque de reyes 2', 1236);
INSERT INTO public.libro VALUES (2329, 1892, 'Uruguay', 'kJRBAAAAYAAJ', NULL, 512, 'http://books.google.com/books/content?id=kJRBAAAAYAAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'Revista del Plata', 1318);
INSERT INTO public.libro VALUES (2332, 2015, 'Ficción', '_LQeswEACAAJ', '9781514257449', 540, NULL, 'Las huestes de los fugaces reyes de Poniente, descompuestas en hordas, asuelan y esquilman una tierra castigada por la guerra e indefensa ante un invierno que se anuncia inusitadamente crudo. Las alianzas nacen y se desvanecen como volutas de humo bajo el viento helado del Norte. Ajena a las intrigas palaciegas, e ignorante del auténtico peligro en ciernes, la Guardia de la Noche se ve desbordada por los salvajes. Y al otro lado del mundo, Daenerys Targaryen intenta reclutar en las Ciudades Libres un ejército con el que desembarcar en su tierra. Martin hace que lo imposible parezca sencillo. Tormenta de espadas confirma Canción de hielo y fuego como un hito de la fantasía épica. Brutal y poética, conmovedora y cruel, la magia de Martin, como la del mundo de Poniente, necesita apenas una pincelada para cautivar al lector, hacerlo reír y llorar, y conseguir que el asombro ceda paso a la más profunda admiración por la serie.', 'Tormenta de Espadas: George R. R. Martin (Spanish Edition)', 1236);
INSERT INTO public.libro VALUES (2333, 2022, 'Fiction', 'i79vEAAAQBAJ', '9781644735848', 845, 'http://books.google.com/books/content?id=i79vEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Canción de hielo y fuego III "La espada llameante dejó a su paso largas estelas de fuego... El acero cantó contra el acero". Arrasados por la guerra, los Siete Reinos pronto sufrirán un larguísimo invierno que se predice excepcionalmente crudo. Mientras la violencia y el clima empeoran, los personajes entrañables e infames que ya conocemos continúan debatiéndose entre feroces batallas y perversas intrigas palaciegas: Joffrey, el cruel rey adolescente, sigue haciendo de las suyas ante el azoro de los propios miembros de su clan, los Lannister; Robb Stark, rey de Invernalia, ha ganado todos sus batallas, pero está perdiendo la guerra; Daenerys, la princesa de los tres dragones, está al frente de un ejército de mercenarios decidida a cumplir su destino: recuperar el reino del que fue despojada. Pero otra fuerza con la que nadie contaba, los Otros, surge desde más allá del Muro de Hielo: un ejército sobrenatural cuyos cuerpos inertes quizá no puedan ser detenidos. Mientras el futuro de este mundo cuelga en la balanza, nadie descansará hasta que los Siete Reinos hayan estallado en una auténtica tormenta de espadas.', 'Tormenta de espadas / A Storm of Swords', 1236);
INSERT INTO public.libro VALUES (2334, NULL, 'Ficción', 'X6a20AEACAAJ', '9788466374958', 0, NULL, NULL, 'Tormenta de espadas (Canción de hielo y fuego 3)', 1318);
