INSERT INTO public.libro VALUES (2339, 2023, 'Fiction', 'QDi9EAAAQBAJ', '9788401032615', 1554, 'http://books.google.com/books/content?id=QDi9EAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 'Los cinco títulos hasta ahora publicados de «Canción de hielo y fuego», Juego de tronos , Choque de reyes , Tormenta de espadas , Festín de cuervos y Danza de dragones , llegan a las librerías en una nueva edición que conquistará tanto a los fans de esta saga épica como a aquellos que esperan la oportunidad perfecta para adentrarse en sus páginas por primera vez. «Larga vida a George Martin... Sacerdote literario, sabedor de su don para el personaje complejo, el lenguaje vívido y la visión salvaje de los mejores narradores.» The New York Times «Se Acerca el Invierno, anunciaba el lema de los Stark, y sin duda había caído con crueldad sobre ellos.» El juego de alianzas, traiciones y engaños para hacerse con el Trono de Hierro se vuelve más despiadado tras la muerte del joven rey Renly Baratheon. Aunque la ambición de los que se disputan la victoria no conoce límites, la amenaza más terrible acecha tanto a los cuatro reyes como a un Poniente devastado por el conflicto. Desde el lejano norte, una horda de bárbaros y gigantes se cierne lentamente sobre los Siete Reinos. Sin embargo, junto al pueblo libre se aproxima un enemigo incluso más estremecedor: los Otros, unos guerreros sobrenaturales que no temen a la muerte porque la conocen muy bien. La Guardia de la Noche, minada y debilitada, tiene los días contados. Su última esperanza recae sobre los hombros de Jon Nieve, bastardo de Invernalia. Puede que el resultado de la guerra por el poder supremo aún esté por decidirse... La crítica ha dicho: «Larga vida a George Martin... Sacerdote literario, sabedor de su don para el personaje complejo, el lenguaje vívido y la visión salvaje de los mejores narradores.» The New York Times «La capacidad de Martin para crear historias apasionantes de intriga es indiscutible.» El Mundo «Entre aquellos que se afanan en la gran tradición épica de la fantasía, Martin es, con diferencia, el mejor.» TIME Magazine «El sobrecogedor alcance de esta epopeya ha hecho que otros escritores de fantasía se lleven las manos a la cabeza.» The Guardian «El escritor de la famosa saga hace tiempo que ha resuelto su porvenir y ha construido su indiscutible trono: el del nuevo rey de la literatura fantástica.» Vanitatis', 'Tormenta de espadas (Canción de Hielo y Fuego 3)', 1236);
