INSERT INTO public.libro VALUES (2343, 1984, 'Eddas', '_VAiAQAAIAAJ', NULL, 204, 'http://books.google.com/books/content?id=_VAiAQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 'Concebida originalmente como una preceptiva para los escaldas escandinavos, la "Edda menor" fue escrita por Snorri hijo de Sturla (1179-1241) en 1220, durante el periodo de esplendor de las letras islandesas antiguas. Modernamente, sin embargo, su mayor atractivo se debe a ser la mejor y más indeleble introducción al sugestivo mundo de la mitología y las leyendas heroicas del mundo nórdico. En ella se cuentan las andanzas de Odín, señor del Valhalla y de las valkirias; de Tor, de Frig y Freya, de Bálder, de Loki, y se traza la cosmogonía de las creencias precristianas. Entre los relatos de corte épico legendario que contiene ocupa un lugar destacado la historia de Sígurd, el héroe que supo matar al dragón Fáfnir y apoderarse del tesoro de los nibelungos. Edición y traducción de Luis Lerate (Alianza).', 'Edda menor', 1537);
INSERT INTO public.libro VALUES (2352, 1870, 'Ficción', 'kCRJAAAAcAAJ', NULL, 582, 'http://books.google.com/books/content?id=kCRJAAAAcAAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, 'A Dictionary of Books Relating to America, from Its Discovery to the Present Time', 1318);
